def _authorization_request_adapter_spec_sha256(value: object) -> str:
    """Validate the closed self-digested adapter bundle retained for recovery."""

    mapping = _closed(
        value,
        _BATCH_AUTHORIZATION_REQUEST_ADAPTER_SPEC_FIELDS,
        "authorization request adapter spec",
    )
    digest = _sha(mapping["spec_sha256"], "adapter_spec.spec_sha256")
    identity_contract_fields = frozenset(
        {
            "contract_id",
            "artifact_kind",
            "schema_name",
            "schema_version",
            "required_fields",
            "optional_fields",
            "required_runtime_names",
        }
    )
    requirement_bundle_fields = frozenset({"requirement", "identity_contract"})
    equivalence_fields = frozenset(
        {
            "contract_id",
            "byte_deterministic",
            "canonical_identity_paths",
            "stable_inventory_paths",
            "scientific_value_paths",
            "qc_evidence_paths",
        }
    )

    def requirement_material(item: object) -> Mapping[str, object]:
        bundle = _closed(item, requirement_bundle_fields, "adapter spec requirement bundle")
        requirement = bundle["requirement"]
        if not isinstance(requirement, Mapping) or any(
            not isinstance(key, str) for key in requirement
        ):
            raise ProjectAuthorityError("adapter spec requirement is not an object")
        contract = _closed(
            bundle["identity_contract"],
            identity_contract_fields,
            "adapter spec requirement identity contract",
        )
        if requirement.get("owning_identity_contract_sha256") != _digest(contract):
            raise ProjectAuthorityError("adapter spec requirement identity contract differs")
        return requirement

    output_contracts = tuple(
        _closed(
            item,
            identity_contract_fields,
            "adapter spec output identity contract",
        )
        for item in mapping["output_identity_contracts"]
    )
    equivalence = _closed(
        mapping["equivalence_contract"],
        equivalence_fields,
        "adapter spec equivalence contract",
    )
    material = {
        "node_kind": mapping["node_kind"],
        "node_version": mapping["node_version"],
        "required_inputs": [
            dict(requirement_material(item)) for item in mapping["required_inputs"]
        ],
        "optional_inputs": [
            dict(requirement_material(item)) for item in mapping["optional_inputs"]
        ],
        "declared_outputs": mapping["declared_outputs"],
        "output_identity_contract_sha256s": [_digest(contract) for contract in output_contracts],
        "compatibility_signature_id": mapping["compatibility_signature_id"],
        "equivalence_contract_sha256": _digest(equivalence),
        "resource_kind": mapping["resource_kind"],
        "dispatch_mode": mapping["dispatch_mode"],
    }
    if _digest(material) != digest:
        raise ProjectAuthorityError("authorization request adapter spec checksum differs")
    return digest


def _process_role_is_valid(*, schema_version: int, role: object) -> bool:
    if type(role) is not str:
        return False
    return role in {
        candidate for _operation, candidate in _PROCESS_OPERATION_ROLES.get(schema_version, ())
    }


def _process_operation_role_is_valid(
    *, schema_version: int, operation: object, role: object
) -> bool:
    if type(operation) is not str or type(role) is not str:
        return False
    return (operation, role) in _PROCESS_OPERATION_ROLES.get(schema_version, ())


class ProjectAuthorityError(ValueError):
    """A project authority record or capability is invalid."""


class ProjectIdentityError(ProjectAuthorityError):
    """Stable project identity or active-locator evidence disagrees."""


class ProjectMutationConflictError(ProjectAuthorityError):
    """Another writer or a newer authority head prevents mutation."""


class ProjectMappingError(ProjectAuthorityError):
    """A QuPath entry mapping is missing, foreign, or ambiguous."""


