def _add_bounded_cleanup_note(
    primary: BaseException,
    cleanup: BaseException,
    *,
    context: str,
) -> None:
    """Best-effort cleanup diagnostics that can never replace the primary."""

    try:
        primary.add_note(f"{context}: {type(cleanup).__name__}: {str(cleanup)[:240]}"[:512])
    except BaseException:
        pass


def _canonical_bytes(value: object) -> bytes:
    try:
        return json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ProjectAuthorityError("value is not canonical JSON") from exc


def _json_depth(value: object) -> int:
    if isinstance(value, Mapping):
        return 1 + max((_json_depth(item) for item in value.values()), default=0)
    if isinstance(value, (list, tuple)):
        return 1 + max((_json_depth(item) for item in value), default=0)
    return 1


def _precheck_json_depth(text: str, *, label: str) -> None:
    """Reject impossible depth before the recursive JSON decoder is entered."""

    depth = 0
    in_string = False
    escaped = False
    for character in text:
        if in_string:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == '"':
                in_string = False
            continue
        if character == '"':
            # A string within twelve open containers is a depth-13 leaf.  At
            # that depth it may also be an object key, but any valid value for
            # that key necessarily has the same forbidden leaf depth.
            if depth >= _ACTIVE_JSON_MAX_DEPTH:
                raise ProjectAuthorityError(f"{label} JSON exceeds depth {_ACTIVE_JSON_MAX_DEPTH}")
            in_string = True
        elif character in "[{":
            depth += 1
            if depth > _ACTIVE_JSON_MAX_DEPTH:
                raise ProjectAuthorityError(f"{label} JSON exceeds depth {_ACTIVE_JSON_MAX_DEPTH}")
        elif character in "]}":
            depth -= 1
        elif character.isspace() or character in ",:":
            continue
        elif depth >= _ACTIVE_JSON_MAX_DEPTH:
            # Number, boolean, null, or malformed token: valid scalar leaves
            # would exceed the ceiling, while malformed input may be rejected
            # early without entering the recursive decoder.
            raise ProjectAuthorityError(f"{label} JSON exceeds depth {_ACTIVE_JSON_MAX_DEPTH}")


def _decode_bounded_canonical_json(
    payload: bytes,
    *,
    max_bytes: int,
    label: str,
) -> object:
    if not isinstance(payload, bytes) or len(payload) > max_bytes:
        raise ProjectAuthorityError(f"{label} exceeds its {max_bytes}-byte maximum")
    try:
        text = payload.decode("utf-8", errors="strict")
        _precheck_json_depth(text, label=label)
        value = json.loads(text)
    except ProjectAuthorityError:
        raise
    except (UnicodeError, json.JSONDecodeError, RecursionError) as exc:
        raise ProjectAuthorityError(f"{label} JSON is invalid") from exc
    try:
        depth = _json_depth(value)
    except RecursionError as exc:
        raise ProjectAuthorityError(f"{label} JSON depth is invalid") from exc
    if depth > _ACTIVE_JSON_MAX_DEPTH:
        raise ProjectAuthorityError(f"{label} JSON exceeds depth {_ACTIVE_JSON_MAX_DEPTH}")
    if _canonical_bytes(value) != payload:
        raise ProjectAuthorityError(f"{label} JSON is not canonical")
    return value


def _directory_identity(status: os.stat_result) -> tuple[int, int, int, int]:
    return (
        stat.S_IFMT(status.st_mode),
        status.st_dev,
        status.st_ino,
        getattr(status, "st_file_attributes", 0)
        & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400),
    )


def _directory_inventory_state(
    status: os.stat_result,
) -> tuple[int, int, int, int, int, int, int, int]:
    return (
        *_directory_identity(status),
        status.st_nlink,
        status.st_size,
        status.st_mtime_ns,
        status.st_ctime_ns,
    )


def _file_state(
    status: os.stat_result,
) -> tuple[int, int, int, int, int, int, int, int]:
    return (
        stat.S_IFMT(status.st_mode),
        status.st_dev,
        status.st_ino,
        status.st_size,
        status.st_nlink,
        status.st_mtime_ns,
        status.st_ctime_ns,
        getattr(status, "st_file_attributes", 0)
        & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400),
    )


@dataclass(slots=True)
class _PinnedDirectoryReadAuthority:
    """Retain and revalidate every component of one absolute directory path."""

    descriptors: list[int]
    named_components: list[tuple[int, str, tuple[int, int, int, int]]]
    label: str

    @property
    def descriptor(self) -> int:
        return self.descriptors[-1]

    def validate(self) -> None:
        for descriptor in self.descriptors:
            try:
                opened = os.fstat(descriptor)
            except OSError as exc:
                raise ProjectAuthorityError(
                    f"{self.label} directory authority is unavailable"
                ) from exc
            if not stat.S_ISDIR(opened.st_mode):
                raise ProjectAuthorityError(f"{self.label} directory authority changed kind")
        for parent_fd, component, expected in self.named_components:
            try:
                named = os.stat(
                    component,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except OSError as exc:
                raise ProjectAuthorityError(
                    f"{self.label} directory authority was replaced"
                ) from exc
            if _directory_identity(named) != expected:
                raise ProjectAuthorityError(f"{self.label} directory authority was replaced")

    def close(self) -> None:
        for descriptor in reversed(self.descriptors):
            os.close(descriptor)
        self.descriptors.clear()
        self.named_components.clear()


@contextmanager
def _pinned_directory_read_authority(
    directory: Path,
    *,
    label: str,
) -> Iterator[_PinnedDirectoryReadAuthority]:
    if os.name != "posix":
        raise ProjectAuthorityError(
            f"{label} requires POSIX descriptor-relative directory authority"
        )
    if not directory.is_absolute() or ".." in directory.parts:
        raise ProjectAuthorityError(f"{label} directory authority is invalid")
    flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    descriptors: list[int] = []
    named_components: list[tuple[int, str, tuple[int, int, int, int]]] = []
    authority = _PinnedDirectoryReadAuthority(
        descriptors=descriptors,
        named_components=named_components,
        label=label,
    )
    try:
        current = os.open(directory.anchor, flags)
        descriptors.append(current)
        for component in directory.parts[1:]:
            child: int | None = None
            try:
                named = os.stat(
                    component,
                    dir_fd=current,
                    follow_symlinks=False,
                )
                child = os.open(component, flags, dir_fd=current)
                opened = os.fstat(child)
            except OSError as exc:
                if child is not None:
                    os.close(child)
                raise ProjectAuthorityError(
                    f"{label} directory authority is unavailable or unsafe"
                ) from exc
            expected = _directory_identity(named)
            if not stat.S_ISDIR(named.st_mode) or _directory_identity(opened) != expected:
                os.close(child)
                raise ProjectAuthorityError(f"{label} directory authority changed while opening")
            named_components.append((current, component, expected))
            descriptors.append(child)
            current = child
        authority.validate()
        yield authority
        authority.validate()
    finally:
        authority.close()


def _read_bounded_file_at(
    directory_fd: int,
    name: str,
    *,
    max_bytes: int,
    label: str,
) -> bytes:
    if not name or name in {".", ".."} or "/" in name or "\x00" in name:
        raise ProjectAuthorityError(f"{label} member name is invalid")
    try:
        named_before = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        descriptor = os.open(
            name,
            os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=directory_fd,
        )
    except OSError as exc:
        raise ProjectAuthorityError(f"{label} cannot be opened safely") from exc
    try:
        opened = os.fstat(descriptor)
        reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
        if (
            not stat.S_ISREG(named_before.st_mode)
            or not stat.S_ISREG(opened.st_mode)
            or named_before.st_nlink != 1
            or opened.st_nlink != 1
            or getattr(named_before, "st_file_attributes", 0) & reparse_flag
            or getattr(opened, "st_file_attributes", 0) & reparse_flag
            or _file_state(named_before) != _file_state(opened)
            or opened.st_size > max_bytes
        ):
            if opened.st_size > max_bytes:
                raise ProjectAuthorityError(f"{label} exceeds its {max_bytes}-byte maximum")
            raise ProjectAuthorityError(f"{label} is not one stable regular file")
        chunks: list[bytes] = []
        remaining = max_bytes + 1
        while remaining:
            chunk = os.read(descriptor, min(remaining, 64 * 1024))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        payload = b"".join(chunks)
        try:
            after = os.fstat(descriptor)
            named_after = os.stat(
                name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
        except OSError as exc:
            raise ProjectAuthorityError(f"{label} changed during bounded read") from exc
        if len(payload) > max_bytes:
            raise ProjectAuthorityError(f"{label} exceeds its {max_bytes}-byte maximum")
        if (
            _file_state(after) != _file_state(opened)
            or _file_state(named_after) != _file_state(opened)
            or len(payload) != opened.st_size
        ):
            raise ProjectAuthorityError(f"{label} changed during bounded read")
        return payload
    finally:
        os.close(descriptor)


def _hash_bounded_file_at(
    directory_fd: int,
    name: str,
    *,
    max_bytes: int,
    label: str,
) -> tuple[str, int]:
    if not name or name in {".", ".."} or "/" in name or "\x00" in name:
        raise ProjectAuthorityError(f"{label} member name is invalid")
    try:
        named_before = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        descriptor = os.open(
            name,
            os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=directory_fd,
        )
    except OSError as exc:
        raise ProjectAuthorityError(f"{label} cannot be opened safely") from exc
    try:
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(named_before.st_mode)
            or not stat.S_ISREG(opened.st_mode)
            or named_before.st_nlink != 1
            or opened.st_nlink != 1
            or _file_state(named_before) != _file_state(opened)
            or opened.st_size > max_bytes
        ):
            if opened.st_size > max_bytes:
                raise ProjectAuthorityError(f"{label} exceeds its bounded hierarchy allowance")
            raise ProjectAuthorityError(f"{label} is not one stable regular file")
        digest = hashlib.sha256()
        byte_count = 0
        while True:
            chunk = os.read(descriptor, min(1024 * 1024, max_bytes + 1 - byte_count))
            if not chunk:
                break
            digest.update(chunk)
            byte_count += len(chunk)
            if byte_count > max_bytes:
                raise ProjectAuthorityError(f"{label} exceeds its bounded hierarchy allowance")
        try:
            after = os.fstat(descriptor)
            named_after = os.stat(
                name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
        except OSError as exc:
            raise ProjectAuthorityError(f"{label} changed while hashing") from exc
        if (
            _file_state(after) != _file_state(opened)
            or _file_state(named_after) != _file_state(opened)
            or byte_count != opened.st_size
        ):
            raise ProjectAuthorityError(f"{label} changed while hashing")
        return digest.hexdigest(), byte_count
    finally:
        os.close(descriptor)


def _inventory_bounded_canonical_json_records(
    root: Path,
    *,
    max_count: int,
    max_record_bytes: int,
    max_inventory_bytes: int,
    label: str,
    allowed_directories: frozenset[str] = frozenset(),
    expected_files: Mapping[str, bytes] | None = None,
    expected_directory_identity: tuple[int, int, int, int] | None = None,
) -> tuple[tuple[Path, Mapping[str, object]], ...]:
    """Read one closed, bounded JSON directory from a retained authority."""

    with _pinned_directory_read_authority(root, label=label) as authority:
        try:
            names_before = tuple(sorted(os.listdir(authority.descriptor)))
            directory_before = os.fstat(authority.descriptor)
        except OSError as exc:
            raise ProjectAuthorityError(f"{label} cannot be inventoried") from exc
        if (
            expected_directory_identity is not None
            and _directory_identity(directory_before) != expected_directory_identity
        ):
            raise ProjectAuthorityError(f"{label} directory identity differs from its authority")
        if len(names_before) > max_count:
            raise ProjectAuthorityError(f"{label} exceeds its {max_count}-member maximum")
        exact_files = {} if expected_files is None else dict(expected_files)
        if any(
            not isinstance(name, str) or not name or "/" in name or not isinstance(payload, bytes)
            for name, payload in exact_files.items()
        ):
            raise ProjectAuthorityError(f"{label} exact-file authority is invalid")
        records: list[tuple[Path, Mapping[str, object]]] = []
        inventory_bytes = 0
        retained_directories: list[
            tuple[int, str, int, tuple[int, int, int, int, int, int, int, int]]
        ] = []
        directory_flags = (
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_NOFOLLOW", 0)
        )
        try:
            for name in names_before:
                if not name or name in {".", ".."} or "/" in name:
                    raise ProjectAuthorityError(f"{label} contains an unsafe member")
                try:
                    status = os.stat(
                        name,
                        dir_fd=authority.descriptor,
                        follow_symlinks=False,
                    )
                except OSError as exc:
                    raise ProjectAuthorityError(f"{label} member is unavailable") from exc
                if stat.S_ISDIR(status.st_mode):
                    if name not in allowed_directories:
                        raise ProjectAuthorityError(f"{label} contains an unknown directory")
                    child: int | None = None
                    try:
                        child = os.open(
                            name,
                            directory_flags,
                            dir_fd=authority.descriptor,
                        )
                        opened = os.fstat(child)
                    except OSError as exc:
                        if child is not None:
                            os.close(child)
                        raise ProjectAuthorityError(f"{label} directory member is unsafe") from exc
                    if _directory_identity(opened) != _directory_identity(status):
                        os.close(child)
                        raise ProjectAuthorityError(
                            f"{label} directory member changed while opening"
                        )
                    retained_directories.append(
                        (
                            authority.descriptor,
                            name,
                            child,
                            _directory_inventory_state(opened),
                        )
                    )
                    continue
                if name in exact_files:
                    expected = exact_files[name]
                    payload = _read_bounded_file_at(
                        authority.descriptor,
                        name,
                        max_bytes=max(max_record_bytes, len(expected)),
                        label=f"{label} exact member",
                    )
                    inventory_bytes += len(payload)
                    if payload != expected:
                        raise ProjectAuthorityError(f"{label} exact member differs")
                    continue
                if not name.endswith(".json"):
                    raise ProjectAuthorityError(f"{label} contains an unsafe member")
                payload = _read_bounded_file_at(
                    authority.descriptor,
                    name,
                    max_bytes=max_record_bytes,
                    label=f"{label} member",
                )
                inventory_bytes += len(payload)
                if inventory_bytes > max_inventory_bytes:
                    raise ProjectAuthorityError(
                        f"{label} exceeds its {max_inventory_bytes}-byte maximum"
                    )
                mapping = _decode_bounded_canonical_json(
                    payload,
                    max_bytes=max_record_bytes,
                    label=f"{label} member",
                )
                if not isinstance(mapping, Mapping):
                    raise ProjectAuthorityError(f"{label} member is not an object")
                records.append((root / name, mapping))
            if not set(exact_files).issubset(names_before):
                raise ProjectAuthorityError(f"{label} lacks its exact authority member")
            try:
                names_after = tuple(sorted(os.listdir(authority.descriptor)))
                directory_after = os.fstat(authority.descriptor)
            except OSError as exc:
                raise ProjectAuthorityError(f"{label} changed during inventory") from exc
            if names_after != names_before or _directory_inventory_state(
                directory_after
            ) != _directory_inventory_state(directory_before):
                raise ProjectAuthorityError(f"{label} changed during inventory")
            for parent_fd, name, child, expected in retained_directories:
                try:
                    child_after = os.fstat(child)
                    named_after = os.stat(
                        name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                except OSError as exc:
                    raise ProjectAuthorityError(f"{label} directory member was replaced") from exc
                if (
                    _directory_inventory_state(child_after) != expected
                    or _directory_identity(named_after) != expected[:4]
                ):
                    raise ProjectAuthorityError(
                        f"{label} directory member changed during inventory"
                    )
            return tuple(records)
        finally:
            for _parent_fd, _name, child, _expected in reversed(retained_directories):
                os.close(child)


def _read_bounded_relative_regular_file(
    owner: Path,
    relative: Path,
    *,
    max_bytes: int,
    label: str,
) -> bytes:
    """Read one member through a retained, no-follow absolute ancestor chain."""

    if relative.is_absolute() or not relative.parts or ".." in relative.parts:
        raise ProjectAuthorityError(f"{label} escapes its authority directory")
    parent = owner.joinpath(*relative.parts[:-1])
    if os.name == "nt":
        authority = Win32FileAuthority()
        retained = None
        try:
            retained = authority.retain_directory(parent, create=False)
            payload = authority.read_bytes(
                retained, relative.parts[-1], max_bytes=max_bytes, label=label
            )
            if not isinstance(payload, bytes):
                raise ProjectAuthorityError(f"{label} is unavailable")
            return payload
        except ProjectAuthorityError:
            raise
        except Exception as error:
            raise ProjectAuthorityError(
                f"{label} cannot be read through retained Windows file handles"
            ) from error
        finally:
            if retained is not None:
                primary = sys.exc_info()[1]
                try:
                    authority.close_directory(retained)
                except BaseException as cleanup:
                    if primary is not None:
                        _add_bounded_cleanup_note(
                            primary, cleanup, context=f"{label} directory cleanup"
                        )
                    else:
                        raise
    with _pinned_directory_read_authority(parent, label=label) as authority:
        return _read_bounded_file_at(
            authority.descriptor,
            relative.parts[-1],
            max_bytes=max_bytes,
            label=label,
        )


def _hash_pinned_entry_member(
    owner: Path,
    relative: Path,
    *,
    hierarchy: bool,
) -> str:
    """Hash one bounded QuPath member through a stable complete inventory."""

    if relative.is_absolute() or not relative.parts or ".." in relative.parts:
        raise ProjectAuthorityError("entry target escapes the project data root")
    if os.name != "posix":
        raise ProjectAuthorityError(
            "entry target proof requires POSIX descriptor-relative authority"
        )
    directory_flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    if not hierarchy:
        parent = owner.joinpath(*relative.parts[:-1])
        with _pinned_directory_read_authority(
            parent,
            label="entry data authority",
        ) as authority:
            digest, _size = _hash_bounded_file_at(
                authority.descriptor,
                relative.parts[-1],
                max_bytes=_ENTRY_HIERARCHY_MAX_BYTES,
                label="entry target file",
            )
            return digest

    hierarchy_root = owner.joinpath(*relative.parts)
    with _pinned_directory_read_authority(
        hierarchy_root,
        label="entry hierarchy authority",
    ) as authority:
        members: list[dict[str, object]] = []
        byte_count = 0
        owned_directory_descriptors: list[int] = []
        retained_directory_inventories: list[
            tuple[
                int | None,
                str | None,
                int,
                tuple[str, ...],
                tuple[int, int, int, int, int, int, int, int],
            ]
        ] = []

        def walk(
            directory_fd: int,
            prefix: str,
            *,
            parent_fd: int | None = None,
            member_name: str | None = None,
        ) -> None:
            nonlocal byte_count
            try:
                names_before = tuple(sorted(os.listdir(directory_fd)))
                directory_before = os.fstat(directory_fd)
            except OSError as exc:
                raise ProjectAuthorityError("entry hierarchy target cannot be inventoried") from exc
            if len(members) + len(names_before) > _ENTRY_HIERARCHY_MAX_COUNT:
                raise ProjectAuthorityError("entry hierarchy target exceeds its member maximum")
            retained_directory_inventories.append(
                (
                    parent_fd,
                    member_name,
                    directory_fd,
                    names_before,
                    _directory_inventory_state(directory_before),
                )
            )
            for name in names_before:
                if not name or "/" in name or name in {".", ".."}:
                    raise ProjectAuthorityError("entry hierarchy target has an invalid member")
                relative_name = f"{prefix}/{name}" if prefix else name
                try:
                    status = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
                except OSError as exc:
                    raise ProjectAuthorityError("entry hierarchy member is unavailable") from exc
                if stat.S_ISDIR(status.st_mode):
                    child: int | None = None
                    try:
                        child = os.open(name, directory_flags, dir_fd=directory_fd)
                        child_opened = os.fstat(child)
                    except OSError as exc:
                        if child is not None:
                            os.close(child)
                        raise ProjectAuthorityError("entry hierarchy directory is unsafe") from exc
                    if _directory_identity(status) != _directory_identity(child_opened):
                        os.close(child)
                        raise ProjectAuthorityError(
                            "entry hierarchy directory changed while opening"
                        )
                    owned_directory_descriptors.append(child)
                    members.append({"path": relative_name, "kind": "directory"})
                    walk(
                        child,
                        relative_name,
                        parent_fd=directory_fd,
                        member_name=name,
                    )
                elif stat.S_ISREG(status.st_mode):
                    remaining = _ENTRY_HIERARCHY_MAX_BYTES - byte_count
                    digest, member_bytes = _hash_bounded_file_at(
                        directory_fd,
                        name,
                        max_bytes=remaining,
                        label="entry hierarchy file",
                    )
                    byte_count += member_bytes
                    members.append(
                        {
                            "path": relative_name,
                            "kind": "file",
                            "sha256": digest,
                            "byte_count": member_bytes,
                        }
                    )
                else:
                    raise ProjectAuthorityError("entry hierarchy target contains an unsafe member")

        try:
            walk(authority.descriptor, "")
            for (
                parent_fd,
                member_name,
                directory_fd,
                names_before,
                directory_before,
            ) in retained_directory_inventories:
                try:
                    names_after = tuple(sorted(os.listdir(directory_fd)))
                    directory_after = os.fstat(directory_fd)
                    named_after = (
                        None
                        if parent_fd is None or member_name is None
                        else os.stat(
                            member_name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                    )
                except OSError as exc:
                    raise ProjectAuthorityError(
                        "entry hierarchy target changed during inventory"
                    ) from exc
                if (
                    names_after != names_before
                    or _directory_inventory_state(directory_after) != directory_before
                    or (
                        named_after is not None
                        and _directory_identity(named_after) != directory_before[:4]
                    )
                ):
                    raise ProjectAuthorityError("entry hierarchy target changed during inventory")
            return _digest(members)
        finally:
            for descriptor in reversed(owned_directory_descriptors):
                os.close(descriptor)


def _digest(value: object) -> str:
    return hashlib.sha256(_canonical_bytes(value)).hexdigest()


def _environment_digest(environment: object) -> str:
    if not isinstance(environment, Mapping):
        raise ProjectAuthorityError("process launch environment must be a mapping")
    for name, value in environment.items():
        if (
            type(name) is not str
            or type(value) is not str
            or not name
            or "\x00" in name
            or "\x00" in value
        ):
            raise ProjectAuthorityError("process launch environment is invalid")
    return _digest({"environment": dict(environment)})


def _project_record_ref(
    value: object,
    *,
    authority_layout_sha256: str,
    family: str,
    scope: Mapping[str, object],
    natural_key: Mapping[str, object],
    field: str,
) -> AuthorityMemberRefV2:
    try:
        ref = (
            value
            if type(value) is AuthorityMemberRefV2
            else AuthorityMemberRefV2.from_mapping(
                value,
                expected_layout_sha256=authority_layout_sha256,
            )
        )
        expected_key = _digest(
            {
                "authority_layout_sha256": authority_layout_sha256,
                "family": family,
                "scope": dict(scope),
                "natural_key": dict(natural_key),
            }
        )
    except (TypeError, ValueError, DurableRecordError) as exc:
        raise ProjectAuthorityError(f"{field} is invalid") from exc
    if (
        ref.authority_layout_sha256 != authority_layout_sha256
        or ref.family != family
        or ref.key_sha256 != expected_key
    ):
        raise ProjectAuthorityError(f"{field} does not match its project record")
    return ref


def _project_record_ref_mapping(value: AuthorityMemberRefV2 | None) -> object:
    return None if value is None else value.to_mapping()


def _sha(value: object, field: str, *, optional: bool = False) -> str | None:
    if optional and value is None:
        return None
    if not isinstance(value, str) or _SHA256.fullmatch(value) is None:
        raise ProjectAuthorityError(f"{field} must be a lowercase SHA-256")
    return value


def _text(value: object, field: str) -> str:
    if not isinstance(value, str) or not value or value != value.strip():
        raise ProjectAuthorityError(f"{field} must be non-empty canonical text")
    if any(ord(character) < 0x20 for character in value):
        raise ProjectAuthorityError(f"{field} contains a control character")
    return value


def _closed(value: object, fields: frozenset[str], field: str) -> Mapping[str, object]:
    if not isinstance(value, Mapping) or any(not isinstance(key, str) for key in value):
        raise ProjectAuthorityError(f"{field} must be an object")
    if frozenset(value) != fields:
        raise ProjectAuthorityError(f"{field} fields are not the current closed schema")
    return value


def _string_mapping(value: Mapping[str, str], field: str) -> Mapping[str, str]:
    if not isinstance(value, Mapping):
        raise ProjectAuthorityError(f"{field} must be a mapping")
    result: dict[str, str] = {}
    for key, item in value.items():
        result[_text(key, f"{field} key")] = _text(item, f"{field} value")
    return MappingProxyType(dict(sorted(result.items())))


def _atomic_replace(path: Path, payload: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    temporary = Path(temporary_name)
    try:
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        _sync_directory(path.parent)
    finally:
        if temporary.exists():
            temporary.unlink()


def _publish_immutable(path: Path, payload: bytes) -> None:
    try:
        publish_immutable_record(
            path,
            payload,
            max_bytes=_DURABLE_RECORD_MAX_BYTES,
            label="immutable authority record",
        )
    except DurableRecordError as exc:
        raise ProjectAuthorityError(f"immutable authority record conflicts: {path}") from exc


def _sync_directory(path: Path) -> None:
    if os.name != "posix":
        return
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def canonical_project_uri(path: Path) -> str:
    """Return the operational local locator without treating it as identity."""
    if not isinstance(path, Path):
        raise ProjectIdentityError("project path must be a Path")
    if not path.name or path.name in {".", ".."}:
        raise ProjectIdentityError("project path must name a file")
    parent = path.parent.resolve(strict=True)
    if parent.is_symlink() or not parent.is_dir():
        raise ProjectIdentityError("project parent must be a real directory")
    candidate = parent / path.name
    if candidate.exists() or candidate.is_symlink():
        try:
            status = candidate.lstat()
        except OSError as exc:
            raise ProjectIdentityError(
                "project final component cannot be inspected safely"
            ) from exc
        reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
        if (
            stat.S_ISLNK(status.st_mode)
            or getattr(status, "st_file_attributes", 0) & reparse_flag
            or not stat.S_ISREG(status.st_mode)
            or status.st_nlink != 1
        ):
            raise ProjectIdentityError("project final component must be one safe regular file")
    return candidate.absolute().as_uri()


_MAX_READ_ONLY_QPPROJ_BYTES = 64 * 1024 * 1024 * 1024


class _PinnedReadOnlyProjectFile:
    """One named regular file pinned for a bounded no-mutation observation."""

    def __init__(self, path: Path, *, max_bytes: int, label: str) -> None:
        if type(max_bytes) is not int or max_bytes < 1:
            raise ProjectAuthorityError(f"{label} byte bound is invalid")
        self._path = Path(path)
        self._label = label
        self._max_bytes = max_bytes
        self._directory_context = None
        self._directory = None
        self._descriptor: int | None = None
        self._pin = None
        self._win32_authority: Win32FileAuthority | None = None
        self._win32_directory: object | None = None
        self._win32_target: object | None = None
        try:
            if os.name == "posix":
                if not self._path.is_absolute() or not self._path.name:
                    raise ProjectIdentityError("read-only target path is invalid")
                self._directory_context = _pinned_directory_read_authority(
                    self._path.parent, label=label
                )
                self._directory = self._directory_context.__enter__()
                initial = os.stat(
                    self._path.name,
                    dir_fd=self._directory.descriptor,
                    follow_symlinks=False,
                )
                _PinnedProjectPath._require_safe_regular(initial)
                self._descriptor = os.open(
                    self._path.name,
                    os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
                    dir_fd=self._directory.descriptor,
                )
                opened = os.fstat(self._descriptor)
                if _file_state(opened) != _file_state(initial):
                    raise ProjectIdentityError("read-only target changed while opening")
            else:
                self._win32_authority = Win32FileAuthority()
                self._win32_directory = self._win32_authority.retain_directory(
                    self._path.parent, create=False
                )
                self._win32_target = self._win32_authority.retain_read_only_target(
                    self._win32_directory, self._path.name
                )
                initial = self._path.lstat()
        except (ProjectIdentityError, OSError, Exception) as exc:
            self.close()
            raise ProjectAuthorityError(f"{label} cannot be retained read-only") from exc
        if initial.st_size > max_bytes:
            self.close()
            raise ProjectAuthorityError(f"{label} exceeds its byte maximum")
        self._state = _file_state(initial)

    def read_bytes(self) -> bytes:
        if os.name == "posix":
            try:
                if self._directory is None or self._descriptor is None:
                    raise ProjectAuthorityError(f"{self._label} pin is closed")
                self._directory.validate()
                before = os.fstat(self._descriptor)
                named = os.stat(
                    self._path.name,
                    dir_fd=self._directory.descriptor,
                    follow_symlinks=False,
                )
                if _file_state(before) != self._state or _file_state(named) != self._state:
                    raise ProjectAuthorityError(f"{self._label} changed after retention")
                os.lseek(self._descriptor, 0, os.SEEK_SET)
                chunks: list[bytes] = []
                remaining = self._max_bytes + 1
                while remaining:
                    chunk = os.read(self._descriptor, min(remaining, 64 * 1024))
                    if not chunk:
                        break
                    chunks.append(chunk)
                    remaining -= len(chunk)
                payload = b"".join(chunks)
                after = os.fstat(self._descriptor)
                named_after = os.stat(
                    self._path.name,
                    dir_fd=self._directory.descriptor,
                    follow_symlinks=False,
                )
                self._directory.validate()
            except ProjectAuthorityError:
                raise
            except (OSError, ProjectIdentityError) as exc:
                raise ProjectAuthorityError(f"{self._label} changed during retained read") from exc
            if (
                len(payload) > self._max_bytes
                or _file_state(after) != self._state
                or _file_state(named_after) != self._state
            ):
                raise ProjectAuthorityError(f"{self._label} changed during retained read")
            return payload
        if self._win32_authority is not None:
            try:
                if self._win32_directory is None or self._win32_target is None:
                    raise ProjectAuthorityError(f"{self._label} pin is closed")
                self._win32_authority.validate_read_only_target_name(
                    self._win32_directory, self._path.name, self._win32_target
                )
                before = self._path.lstat()
                if _file_state(before) != self._state:
                    raise ProjectAuthorityError(f"{self._label} changed after retention")
                payload = self._win32_authority.read_read_only_target(
                    self._win32_target, maximum_bytes=self._max_bytes
                )
                after = self._path.lstat()
                self._win32_authority.validate_read_only_target_name(
                    self._win32_directory, self._path.name, self._win32_target
                )
            except ProjectAuthorityError:
                raise
            except Exception as exc:
                raise ProjectAuthorityError(f"{self._label} changed during retained read") from exc
            if type(payload) is not bytes or _file_state(after) != self._state:
                raise ProjectAuthorityError(f"{self._label} changed during retained read")
            return payload
        try:
            assert self._pin is not None
            self._pin.validate(require_exists=True)
            before = self._path.lstat()
            if _file_state(before) != self._state or before.st_size > self._max_bytes:
                raise ProjectAuthorityError(f"{self._label} changed after retention")
            payload = self._pin.read_bytes()
            after = self._path.lstat()
        except ProjectAuthorityError:
            raise
        except (ProjectIdentityError, OSError) as exc:
            raise ProjectAuthorityError(f"{self._label} changed during retained read") from exc
        if (
            type(payload) is not bytes
            or len(payload) > self._max_bytes
            or _file_state(after) != self._state
        ):
            raise ProjectAuthorityError(f"{self._label} changed during retained read")
        return payload

    def validate(self) -> None:
        self.read_bytes()

    def close(self) -> None:
        descriptor = getattr(self, "_descriptor", None)
        if descriptor is not None:
            self._descriptor = None
            os.close(descriptor)
        directory_context = getattr(self, "_directory_context", None)
        if directory_context is not None:
            self._directory_context = None
            self._directory = None
            directory_context.__exit__(None, None, None)
        win32_authority = getattr(self, "_win32_authority", None)
        win32_target = getattr(self, "_win32_target", None)
        win32_directory = getattr(self, "_win32_directory", None)
        if win32_authority is not None:
            self._win32_target = None
            self._win32_directory = None
            self._win32_authority = None
            failure: BaseException | None = None
            if win32_target is not None:
                try:
                    win32_authority.close_read_only_target(win32_target)
                except BaseException as exc:
                    failure = exc
            if win32_directory is not None:
                try:
                    win32_authority.close_directory(win32_directory)
                except BaseException as exc:
                    if failure is None:
                        failure = exc
                    else:
                        _add_bounded_cleanup_note(
                            failure,
                            exc,
                            context="additional Windows read-only directory cleanup failure",
                        )
            if failure is not None:
                raise failure
        pin = getattr(self, "_pin", None)
        if pin is not None:
            self._pin = None
            pin.close()


def verify_read_only_project_snapshot(
    *, project_path: Path, project_uri: str, qpproj_snapshot_sha256: str
) -> None:
    """Verify one canonical named project against its owner's current digest.

    This authenticates pipeline snapshot authority without opening a QuPath
    project or acquiring mutation authority. The retained file reader owns
    no-follow access and name revalidation on both supported platforms.
    """

    expected = _sha(qpproj_snapshot_sha256, "qpproj_snapshot_sha256")
    try:
        if (
            not project_path.is_absolute()
            or project_path.suffix != ".qpproj"
            or project_path.as_uri() != project_uri
            or canonical_project_uri(project_path) != project_uri
        ):
            raise ProjectAuthorityError("read-only project locator differs")
    except (ProjectIdentityError, OSError, ValueError) as exc:
        raise ProjectAuthorityError("read-only project locator is invalid") from exc
    pin = _PinnedReadOnlyProjectFile(
        project_path,
        max_bytes=_MAX_READ_ONLY_QPPROJ_BYTES,
        label="current project snapshot",
    )
    try:
        if hashlib.sha256(pin.read_bytes()).hexdigest() != expected:
            raise ProjectAuthorityError("current project snapshot bytes differ")
    finally:
        pin.close()


class _PinnedProjectPath:
    """Pin one real parent and a no-follow project final component."""

    def __init__(self, path: Path) -> None:
        self.path = Path(path)
        self.parent = self.path.parent.resolve(strict=True)
        self.name = self.path.name
        self._parent_descriptor: int | None = None
        self._win32_authority: Win32FileAuthority | None = None
        self._win32_parent: object | None = None
        self._win32_final: object | None = None
        self._final_descriptor: int | None = None
        self._retired_final_descriptors: list[int] = []
        self._retired_win32_finals: list[object] = []
        if not self.name or self.name in {".", ".."}:
            raise ProjectIdentityError("project path must name a file")
        win32_authority: Win32FileAuthority | None = None
        win32_parent: object | None = None
        try:
            parent_before = self.parent.lstat()
            if (
                not stat.S_ISDIR(parent_before.st_mode)
                or stat.S_ISLNK(parent_before.st_mode)
                or getattr(parent_before, "st_file_attributes", 0)
                & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
            ):
                raise ProjectIdentityError("project parent is unsafe")
            if os.name == "nt":
                win32_authority = Win32FileAuthority()
                win32_parent = win32_authority.retain_directory(self.parent, create=False)
                win32_authority.validate_directory(win32_parent)
                opened = self.parent.lstat()
            else:
                descriptor = os.open(
                    self.parent,
                    os.O_RDONLY
                    | getattr(os, "O_DIRECTORY", 0)
                    | getattr(os, "O_CLOEXEC", 0)
                    | getattr(os, "O_NOFOLLOW", 0),
                )
                self._parent_descriptor = descriptor
                opened = os.fstat(descriptor)
        except BaseException as primary:
            if win32_authority is not None and win32_parent is not None:
                try:
                    win32_authority.close_directory(win32_parent)
                except BaseException as cleanup:
                    _add_bounded_cleanup_note(
                        primary,
                        cleanup,
                        context="additional project-parent pin cleanup failure",
                    )
            if isinstance(primary, ProjectIdentityError):
                raise
            if not isinstance(primary, Exception):
                raise
            exc = primary
            raise ProjectIdentityError("project parent cannot be pinned") from exc
        self._parent_identity = (opened.st_dev, opened.st_ino)
        if self._parent_identity != (parent_before.st_dev, parent_before.st_ino):
            if self._parent_descriptor is not None:
                os.close(self._parent_descriptor)
                self._parent_descriptor = None
            if win32_authority is not None and win32_parent is not None:
                win32_authority.close_directory(win32_parent)
            raise ProjectIdentityError("project parent changed while being pinned")
        self._win32_authority = win32_authority
        self._win32_parent = win32_parent
        try:
            final = self._final_status()
            self._final_identity = None
            self._existed_at_initial_pin = final is not None
            if final is not None:
                self._open_final(final)
        except BaseException:
            self.close()
            raise

    @staticmethod
    def _require_safe_regular(status: os.stat_result) -> None:
        reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
        if (
            stat.S_ISLNK(status.st_mode)
            or getattr(status, "st_file_attributes", 0) & reparse_flag
            or not stat.S_ISREG(status.st_mode)
            or status.st_nlink != 1
        ):
            raise ProjectIdentityError("project final component must be one safe regular file")

    @property
    def exists_at_pin(self) -> bool:
        return bool(
            getattr(
                self,
                "_existed_at_initial_pin",
                self._final_identity is not None,
            )
        )

    @property
    def retained_file_identity(self) -> tuple[int, int] | Win32FileIdentity:
        self.validate(require_exists=True)
        if self._final_identity is None:
            raise ProjectIdentityError("project final component identity is unavailable")
        if os.name == "nt":
            if self._win32_authority is None or self._win32_final is None:
                raise ProjectIdentityError("project final component pin is unavailable")
            try:
                return self._win32_authority.mutable_target_identity(
                    self._win32_final,
                    allow_unlinked_predecessor=False,
                )
            except Exception as exc:
                raise ProjectIdentityError("project final component identity changed") from exc
        return self._final_identity

    def _final_status(self) -> os.stat_result | None:
        descriptor = self._parent_descriptor
        if descriptor is None and self._win32_parent is None:
            raise ProjectIdentityError("project target pin is closed")
        try:
            if os.name == "posix":
                result = os.stat(
                    self.name,
                    dir_fd=descriptor,
                    follow_symlinks=False,
                )
            else:
                result = (self.parent / self.name).lstat()
        except FileNotFoundError:
            return None
        except OSError as exc:
            raise ProjectIdentityError(
                "project final component cannot be inspected safely"
            ) from exc
        self._require_safe_regular(result)
        return result

    def _open_final(self, expected: os.stat_result) -> None:
        parent_descriptor = self._parent_descriptor
        if parent_descriptor is None and self._win32_parent is None:
            raise ProjectIdentityError("project target pin is closed")
        if os.name == "nt":
            assert self._win32_authority is not None
            assert self._win32_parent is not None
            try:
                retained = self._win32_authority.retain_mutable_target(
                    self._win32_parent,
                    self.name,
                )
            except Exception as exc:
                raise ProjectIdentityError("project final component cannot be pinned") from exc
            self._win32_final = retained
            self._final_identity = (expected.st_dev, expected.st_ino)
            return
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
        try:
            descriptor = os.open(
                self.name,
                flags,
                dir_fd=parent_descriptor,
            )
        except OSError as exc:
            raise ProjectIdentityError("project final component cannot be pinned") from exc
        opened = os.fstat(descriptor)
        try:
            self._require_safe_regular(opened)
            if (opened.st_dev, opened.st_ino) != (expected.st_dev, expected.st_ino):
                raise ProjectIdentityError("project final component changed while being pinned")
        except BaseException:
            os.close(descriptor)
            raise
        self._final_descriptor = descriptor
        self._final_identity = (opened.st_dev, opened.st_ino)

    def _validate_parent(self) -> None:
        descriptor = self._parent_descriptor
        if descriptor is None and self._win32_parent is None:
            raise ProjectIdentityError("project target pin is closed")
        try:
            parent = self.parent.lstat()
        except OSError as exc:
            raise ProjectIdentityError("project parent changed after pinning") from exc
        if (
            not stat.S_ISDIR(parent.st_mode)
            or stat.S_ISLNK(parent.st_mode)
            or getattr(parent, "st_file_attributes", 0)
            & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
            or (parent.st_dev, parent.st_ino) != self._parent_identity
        ):
            raise ProjectIdentityError("project parent changed after pinning")
        if descriptor is not None:
            opened_parent = os.fstat(descriptor)
            if (opened_parent.st_dev, opened_parent.st_ino) != self._parent_identity:
                raise ProjectIdentityError("pinned project parent changed")
        else:
            assert self._win32_authority is not None
            assert self._win32_parent is not None
            try:
                self._win32_authority.validate_directory(self._win32_parent)
            except BaseException as exc:
                raise ProjectIdentityError("pinned project parent changed") from exc

    def validate(
        self,
        *,
        require_exists: bool,
        allow_initial_creation: bool = False,
    ) -> None:
        descriptor = self._parent_descriptor
        self._validate_parent()
        final = self._final_status()
        if final is None:
            if require_exists or self._final_identity is not None:
                raise ProjectIdentityError("project final component changed after pinning")
            return
        observed = (final.st_dev, final.st_ino)
        if self._final_identity is None:
            if not allow_initial_creation:
                raise ProjectIdentityError("project final component changed after pinning")
            self._final_identity = observed
            self._open_final(final)
        elif observed != self._final_identity:
            raise ProjectIdentityError("project final component changed after pinning")
        if os.name == "nt":
            if self._win32_final is None:
                raise ProjectIdentityError("project final component pin is unavailable")
            assert self._win32_authority is not None
            assert self._win32_parent is not None
            try:
                self._win32_authority.mutable_target_identity(
                    self._win32_final,
                    allow_unlinked_predecessor=False,
                )
                self._win32_authority.validate_mutable_target_name(
                    self._win32_parent,
                    self.name,
                    self._win32_final,
                )
            except Exception as exc:
                raise ProjectIdentityError("project final component changed after pinning") from exc
        else:
            if self._final_descriptor is None:
                raise ProjectIdentityError("project final component pin is unavailable")
            retained = os.fstat(self._final_descriptor)
            self._require_safe_regular(retained)
            if (retained.st_dev, retained.st_ino) != self._final_identity:
                raise ProjectIdentityError("project final component changed after pinning")

    def _successor_predecessor_identity(self) -> object | None:
        """Return the retained predecessor without trusting its current name."""

        if self._final_identity is None:
            return None
        if os.name == "nt":
            if self._win32_final is None or self._win32_authority is None:
                raise ProjectIdentityError("project final component pin is unavailable")
            try:
                return self._win32_authority.mutable_target_identity(
                    self._win32_final,
                    allow_unlinked_predecessor=True,
                )
            except Exception as exc:
                raise ProjectIdentityError("project predecessor descriptor changed") from exc
        if self._final_descriptor is None:
            raise ProjectIdentityError("project final component pin is unavailable")
        try:
            retained = os.fstat(self._final_descriptor)
        except OSError as exc:
            raise ProjectIdentityError("project predecessor descriptor changed") from exc
        if (
            not stat.S_ISREG(retained.st_mode)
            or retained.st_nlink not in {0, 1}
            or (retained.st_dev, retained.st_ino) != self._final_identity
        ):
            raise ProjectIdentityError("project predecessor descriptor changed")
        return self._final_identity

    @staticmethod
    def _hash_successor_descriptor(descriptor: int) -> str:
        before = os.fstat(descriptor)
        _PinnedProjectPath._require_safe_regular(before)
        os.lseek(descriptor, 0, os.SEEK_SET)
        digest = hashlib.sha256()
        while True:
            chunk = os.read(descriptor, 1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
        after = os.fstat(descriptor)
        if (
            after.st_dev,
            after.st_ino,
            after.st_size,
        ) != (
            before.st_dev,
            before.st_ino,
            before.st_size,
        ):
            raise ProjectIdentityError("project successor changed during authenticated read")
        return digest.hexdigest()

    def _accept_authenticated_successor(
        self,
        *,
        predecessor_identity: object | None,
        expected_sha256: str,
    ) -> None:
        """Repin one exact post-drain successor without relaxing normal checks."""

        if _SHA256.fullmatch(expected_sha256) is None:
            raise ProjectIdentityError("project successor digest is invalid")
        if self._successor_predecessor_identity() != predecessor_identity:
            raise ProjectIdentityError("project predecessor descriptor changed")
        self._validate_parent()
        if os.name == "nt":
            assert self._win32_authority is not None
            assert self._win32_parent is not None
            successor: object | None = None
            try:
                successor = self._win32_authority.retain_mutable_target(
                    self._win32_parent,
                    self.name,
                )
                observed_sha256 = self._win32_authority.hash_mutable_target(successor)
                self._win32_authority.validate_mutable_target_name(
                    self._win32_parent,
                    self.name,
                    successor,
                )
            except Exception as exc:
                if successor is not None:
                    try:
                        self._win32_authority.close_mutable_target(successor)
                    except BaseException as cleanup:
                        self._retired_win32_finals.append(successor)
                        _add_bounded_cleanup_note(
                            exc,
                            cleanup,
                            context="project successor HANDLE cleanup failed",
                        )
                raise ProjectIdentityError(
                    "project successor changed during authentication"
                ) from exc
            if observed_sha256 != expected_sha256:
                primary = ProjectIdentityError(
                    "project successor digest differs from authenticated evidence"
                )
                try:
                    self._win32_authority.close_mutable_target(successor)
                except BaseException as cleanup:
                    getattr(self, "_retired_win32_finals", []).append(successor)
                    _add_bounded_cleanup_note(
                        primary,
                        cleanup,
                        context="project successor HANDLE cleanup failed",
                    )
                raise primary
            prior = self._win32_final
            prior_final_identity = self._final_identity
            try:
                final = self._final_status()
                if final is None:
                    raise ProjectIdentityError("project successor name disappeared before adoption")
            except BaseException as primary:
                try:
                    self._win32_authority.close_mutable_target(successor)
                except BaseException as cleanup:
                    getattr(self, "_retired_win32_finals", []).append(successor)
                    _add_bounded_cleanup_note(
                        primary,
                        cleanup,
                        context="project successor HANDLE cleanup failed",
                    )
                if isinstance(primary, ProjectIdentityError):
                    raise
                if isinstance(primary, Exception):
                    raise ProjectIdentityError(
                        "project successor changed before adoption"
                    ) from primary
                raise
            self._win32_final = successor
            self._final_identity = (final.st_dev, final.st_ino)
            try:
                self.validate(require_exists=True)
            except BaseException as primary:
                self._win32_final = prior
                self._final_identity = prior_final_identity
                try:
                    self._win32_authority.close_mutable_target(successor)
                except BaseException as cleanup:
                    getattr(self, "_retired_win32_finals", []).append(successor)
                    _add_bounded_cleanup_note(
                        primary,
                        cleanup,
                        context="project successor HANDLE cleanup failed",
                    )
                raise
            if prior is not None and prior is not successor:
                try:
                    self._win32_authority.close_mutable_target(prior)
                except BaseException as cleanup:
                    getattr(self, "_retired_win32_finals", []).append(prior)
                    primary = ProjectIdentityError(
                        "project successor accepted but predecessor HANDLE " "cleanup failed"
                    )
                    _add_bounded_cleanup_note(
                        primary,
                        cleanup,
                        context="project predecessor HANDLE cleanup failed",
                    )
                    if isinstance(cleanup, Exception):
                        raise primary from cleanup
                    raise
            return

        parent_descriptor = self._parent_descriptor
        assert parent_descriptor is not None
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
        successor_descriptor: int | None = None
        try:
            successor_descriptor = os.open(
                self.name,
                flags,
                dir_fd=parent_descriptor,
            )
            successor_status = os.fstat(successor_descriptor)
            self._require_safe_regular(successor_status)
            observed_sha256 = self._hash_successor_descriptor(successor_descriptor)
            named = os.stat(
                self.name,
                dir_fd=parent_descriptor,
                follow_symlinks=False,
            )
            self._require_safe_regular(named)
            successor_identity = (
                successor_status.st_dev,
                successor_status.st_ino,
            )
            if (named.st_dev, named.st_ino) != successor_identity:
                raise ProjectIdentityError(
                    "project successor name changed after authenticated read"
                )
            self._validate_parent()
            if observed_sha256 != expected_sha256:
                raise ProjectIdentityError(
                    "project successor digest differs from authenticated evidence"
                )
            predecessor_descriptor = self._final_descriptor
            if successor_identity == self._final_identity:
                self.validate(require_exists=True)
                return
            self._final_descriptor = successor_descriptor
            self._final_identity = successor_identity
            accepted_descriptor = successor_descriptor
            successor_descriptor = None
            try:
                self.validate(require_exists=True)
            except BaseException as primary:
                self._final_descriptor = predecessor_descriptor
                self._final_identity = predecessor_identity  # type: ignore[assignment]
                try:
                    os.close(accepted_descriptor)
                except BaseException as cleanup:
                    self._retired_final_descriptors.append(accepted_descriptor)
                    _add_bounded_cleanup_note(
                        primary,
                        cleanup,
                        context="project successor descriptor cleanup failed",
                    )
                raise
            if predecessor_descriptor is not None:
                try:
                    os.close(predecessor_descriptor)
                except BaseException as cleanup:
                    getattr(self, "_retired_final_descriptors", []).append(predecessor_descriptor)
                    primary = ProjectIdentityError(
                        "project successor accepted but predecessor descriptor " "cleanup failed"
                    )
                    _add_bounded_cleanup_note(
                        primary,
                        cleanup,
                        context="project predecessor descriptor cleanup failed",
                    )
                    if isinstance(cleanup, Exception):
                        raise primary from cleanup
                    raise
        except OSError as exc:
            raise ProjectIdentityError("project successor cannot be opened safely") from exc
        finally:
            if successor_descriptor is not None:
                primary = sys.exc_info()[1]
                try:
                    os.close(successor_descriptor)
                except BaseException as cleanup:
                    getattr(self, "_retired_final_descriptors", []).append(successor_descriptor)
                    if primary is not None:
                        _add_bounded_cleanup_note(
                            primary,
                            cleanup,
                            context="project successor descriptor cleanup failed",
                        )
                    elif isinstance(cleanup, Exception):
                        raise ProjectIdentityError(
                            "project successor descriptor cleanup failed"
                        ) from cleanup
                    else:
                        raise

    def read_bytes(self) -> bytes:
        self.validate(require_exists=True)
        if os.name == "nt":
            if self._win32_authority is None or self._win32_final is None:
                raise ProjectIdentityError("project final component pin is unavailable")
            try:
                payload = self._win32_authority.read_mutable_target(self._win32_final)
                self._win32_authority.validate_mutable_target_name(
                    self._win32_parent,
                    self.name,
                    self._win32_final,
                )
                self.validate(require_exists=True)
                return payload
            except ProjectIdentityError:
                raise
            except Exception as exc:
                raise ProjectIdentityError(
                    "project final component changed during retained read"
                ) from exc
        descriptor = self._parent_descriptor
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
        try:
            if os.name == "posix":
                assert descriptor is not None
                opened = os.open(self.name, flags, dir_fd=descriptor)
            else:
                opened = os.open(self.parent / self.name, flags)
        except OSError as exc:
            raise ProjectIdentityError("project final component cannot be opened safely") from exc
        try:
            status = os.fstat(opened)
            self._require_safe_regular(status)
            if (status.st_dev, status.st_ino) != self._final_identity:
                raise ProjectIdentityError("project final component changed after pinning")
            chunks: list[bytes] = []
            while True:
                chunk = os.read(opened, 1024 * 1024)
                if not chunk:
                    break
                chunks.append(chunk)
            after = os.fstat(opened)
            if (after.st_dev, after.st_ino, after.st_size) != (
                status.st_dev,
                status.st_ino,
                status.st_size,
            ):
                raise ProjectIdentityError("project final component changed during read")
            self.validate(require_exists=True)
            return b"".join(chunks)
        finally:
            primary = sys.exc_info()[1]
            try:
                os.close(opened)
            except BaseException as cleanup:
                self._retired_final_descriptors.append(opened)
                if primary is not None:
                    _add_bounded_cleanup_note(
                        primary,
                        cleanup,
                        context="project read descriptor cleanup failed",
                    )
                elif isinstance(cleanup, Exception):
                    raise ProjectIdentityError(
                        "project read descriptor cleanup failed"
                    ) from cleanup
                else:
                    raise

    def publish_identity_sidecar(
        self,
        payload: bytes,
        *,
        clone_source_sidecar_sha256: str | None = None,
    ) -> None:
        """Publish the project sidecar through the already-pinned parent."""

        self.validate(require_exists=self.exists_at_pin)
        sidecar = Path(f"{self.path}.mif-project-identity.json")
        if self._win32_parent is None:
            if clone_source_sidecar_sha256 is None:
                _publish_immutable(sidecar, payload)
                return
            if sidecar.is_symlink() or not sidecar.is_file():
                raise ProjectIdentityError("cloned destination identity sidecar changed")
            observed = sidecar.read_bytes()
            if observed == payload:
                return
            if hashlib.sha256(observed).hexdigest() != clone_source_sidecar_sha256:
                raise ProjectIdentityError("cloned destination identity sidecar changed")
            _atomic_replace(sidecar, payload)
            return

        authority = self._win32_authority
        retained = self._win32_parent
        assert authority is not None
        sidecar_name = f"{self.name}.mif-project-identity.json"
        try:
            if clone_source_sidecar_sha256 is None:
                authority.publish_immutable(
                    retained,
                    sidecar_name,
                    payload,
                    max_bytes=_DURABLE_RECORD_MAX_BYTES,
                    label="project identity sidecar",
                )
                return
            observed = authority.read_immutable(
                retained,
                sidecar_name,
                max_bytes=_DURABLE_RECORD_MAX_BYTES,
                label="project identity sidecar",
                optional=True,
            )
            if observed is None:
                raise ProjectIdentityError("cloned destination identity sidecar changed")
            if observed == payload:
                return
            if hashlib.sha256(observed).hexdigest() != clone_source_sidecar_sha256:
                raise ProjectIdentityError("cloned destination identity sidecar changed")
            authority.replace_bytes(
                retained,
                sidecar_name,
                payload,
                max_bytes=_DURABLE_RECORD_MAX_BYTES,
                label="project identity sidecar",
            )
        except ProjectIdentityError:
            raise
        except Exception as exc:
            raise ProjectAuthorityError(f"immutable authority record conflicts: {sidecar}") from exc

    def close(self) -> None:
        failures: list[BaseException] = []
        for descriptor in reversed(tuple(getattr(self, "_retired_final_descriptors", ()))):
            try:
                os.close(descriptor)
            except BaseException as exc:
                failures.append(exc)
        if hasattr(self, "_retired_final_descriptors"):
            self._retired_final_descriptors.clear()
        if self._final_descriptor is not None:
            try:
                os.close(self._final_descriptor)
            except BaseException as exc:
                failures.append(exc)
            self._final_descriptor = None
        if getattr(self, "_win32_authority", None) is not None:
            for retained in reversed(tuple(getattr(self, "_retired_win32_finals", ()))):
                try:
                    self._win32_authority.close_mutable_target(retained)
                except BaseException as exc:
                    failures.append(exc)
            if hasattr(self, "_retired_win32_finals"):
                self._retired_win32_finals.clear()
        if getattr(self, "_win32_final", None) is not None:
            assert self._win32_authority is not None
            try:
                self._win32_authority.close_mutable_target(self._win32_final)
            except BaseException as exc:
                failures.append(exc)
            self._win32_final = None
        if self._parent_descriptor is not None:
            try:
                os.close(self._parent_descriptor)
            except BaseException as exc:
                failures.append(exc)
            self._parent_descriptor = None
        if self._win32_parent is not None:
            assert self._win32_authority is not None
            try:
                self._win32_authority.close_directory(self._win32_parent)
            except BaseException as exc:
                failures.append(exc)
            self._win32_parent = None
            self._win32_authority = None
        if failures:
            primary = failures[0]
            for cleanup in failures[1:]:
                _add_bounded_cleanup_note(
                    primary,
                    cleanup,
                    context="additional project path pin cleanup failure",
                )
            if isinstance(primary, ProjectAuthorityError):
                raise primary
            if isinstance(primary, Exception):
                error = ProjectIdentityError("project path pin cleanup failed")
                for cleanup in failures[1:]:
                    _add_bounded_cleanup_note(
                        error,
                        cleanup,
                        context="additional project path pin cleanup failure",
                    )
                raise error from primary
            raise primary


@dataclass(frozen=True, slots=True)
class ProjectIdentityRecord:
    schema_name: Literal["mif-qupath-project-identity"]
    schema_version: Literal[2]
    authority_layout_sha256: str
    project_identity_ref: AuthorityMemberRefV2
    project_uuid: str
    origin_kind: Literal["created", "adopted_existing", "cloned_as_new"]
    origin_qpproj_sha256: str | None
    predecessor_project_identity_sha256: str | None
    project_identity_sha256: str

    def __post_init__(self) -> None:
        """Validate the ProjectIdentityRecord fields when the record is constructed.

        The checks cover ``authority_layout_sha256``, ``project_uuid``, ``origin_kind``,
        ``origin_qpproj_sha256``, ``predecessor_project_identity_sha256``,
        ``project_identity_sha256``. Invalid field types, values or combinations raise the
        declared validation error before this instance can be used by its caller."""

        if self.schema_name != "mif-qupath-project-identity" or self.schema_version != 2:
            raise ProjectIdentityError("project identity schema is unsupported")
        _sha(self.authority_layout_sha256, "authority_layout_sha256")
        try:
            parsed_uuid = uuid.UUID(self.project_uuid)
        except (ValueError, AttributeError, TypeError) as exc:
            raise ProjectIdentityError("project_uuid must be UUIDv4") from exc
        if parsed_uuid.version != 4 or parsed_uuid.variant != uuid.RFC_4122:
            raise ProjectIdentityError("project_uuid must be RFC UUIDv4")
        if str(parsed_uuid) != self.project_uuid:
            raise ProjectIdentityError("project_uuid must be lowercase canonical text")
        if self.origin_kind not in {"created", "adopted_existing", "cloned_as_new"}:
            raise ProjectIdentityError("project identity origin is invalid")
        origin = _sha(self.origin_qpproj_sha256, "origin_qpproj_sha256", optional=True)
        predecessor = _sha(
            self.predecessor_project_identity_sha256,
            "predecessor_project_identity_sha256",
            optional=True,
        )
        if self.origin_kind == "created" and (origin is not None or predecessor is not None):
            raise ProjectIdentityError("created identity cannot have origin digests")
        if self.origin_kind == "adopted_existing" and (origin is None or predecessor is not None):
            raise ProjectIdentityError("adopted identity requires only origin qpproj digest")
        if self.origin_kind == "cloned_as_new" and (origin is None or predecessor is None):
            raise ProjectIdentityError("cloned identity requires source snapshot and predecessor")
        digest = _sha(self.project_identity_sha256, "project_identity_sha256")
        if digest != _digest(self._identity_mapping()):
            raise ProjectIdentityError("project identity checksum is not canonical")
        object.__setattr__(
            self,
            "project_identity_ref",
            _project_record_ref(
                self.project_identity_ref,
                authority_layout_sha256=self.authority_layout_sha256,
                family="project_identity",
                scope={"project_identity_sha256": self.project_identity_sha256},
                natural_key={},
                field="project_identity_ref",
            ),
        )

    def _identity_mapping(self) -> dict[str, object]:
        return {
            "schema_name": self.schema_name,
            "schema_version": self.schema_version,
            "authority_layout_sha256": self.authority_layout_sha256,
            "project_uuid": self.project_uuid,
            "origin_kind": self.origin_kind,
            "origin_qpproj_sha256": self.origin_qpproj_sha256,
            "predecessor_project_identity_sha256": self.predecessor_project_identity_sha256,
        }

    def to_mapping(self) -> dict[str, object]:
        return {
            **self._identity_mapping(),
            "project_identity_ref": self.project_identity_ref.to_mapping(),
            "project_identity_sha256": self.project_identity_sha256,
        }

    @classmethod
    def create(
        cls,
        *,
        authority: ProjectAuthorityV2,
        origin_kind: Literal["created", "adopted_existing", "cloned_as_new"],
        origin_qpproj_sha256: str | None = None,
        predecessor_project_identity_sha256: str | None = None,
    ) -> "ProjectIdentityRecord":
        if not isinstance(authority, ProjectAuthorityV2):
            raise ProjectIdentityError("project identity requires retained authority v2")
        identity = {
            "schema_name": "mif-qupath-project-identity",
            "schema_version": 2,
            "authority_layout_sha256": authority.authority_layout_sha256,
            "project_uuid": str(uuid.uuid4()),
            "origin_kind": origin_kind,
            "origin_qpproj_sha256": origin_qpproj_sha256,
            "predecessor_project_identity_sha256": predecessor_project_identity_sha256,
        }
        identity_sha256 = _digest(identity)
        return cls(
            **identity,
            project_identity_ref=authority.ref(
                "project_identity",
                scope={"project_identity_sha256": identity_sha256},
                natural_key={},
            ),
            project_identity_sha256=identity_sha256,
        )  # type: ignore[arg-type]

    @classmethod
    def from_mapping(cls, value: object) -> "ProjectIdentityRecord":
        fields = frozenset(
            {
                "schema_name",
                "schema_version",
                "authority_layout_sha256",
                "project_identity_ref",
                "project_uuid",
                "origin_kind",
                "origin_qpproj_sha256",
                "predecessor_project_identity_sha256",
                "project_identity_sha256",
            }
        )
        material = dict(_closed(value, fields, "project identity"))
        try:
            material["project_identity_ref"] = AuthorityMemberRefV2.from_mapping(
                material["project_identity_ref"],
                expected_layout_sha256=material["authority_layout_sha256"],  # type: ignore[arg-type]
            )
        except DurableRecordError as exc:
            raise ProjectIdentityError("project identity ref is invalid") from exc
        return cls(**material)  # type: ignore[arg-type]


@dataclass(frozen=True, slots=True)
class ProjectLocatorIdentityRecord:
    schema_name: Literal["mif-qupath-project-locator-identity"]
    schema_version: Literal[1]
    project_uri: str
    project_identity_sha256: str
    lifecycle: Literal["active", "retired"]
    successor_project_uri: str | None
    relocation_authority_head_sha256: str | None
    locator_identity_sha256: str

    def __post_init__(self) -> None:
        """Validate the ProjectLocatorIdentityRecord fields when the record is constructed.

        The checks cover ``project_uri``, ``project_identity_sha256``, ``lifecycle``,
        ``schema_name``, ``schema_version``, ``locator_identity_sha256``. Invalid field
        types, values or combinations raise the declared validation error before this
        instance can be used by its caller."""

        if self.schema_name != "mif-qupath-project-locator-identity" or self.schema_version != 1:
            raise ProjectAuthorityError("locator identity schema is unsupported")
        canonical = canonical_project_uri(_project_path_from_uri(self.project_uri))
        if canonical != self.project_uri:
            raise ProjectAuthorityError("locator identity URI is not canonical")
        _sha(self.project_identity_sha256, "project_identity_sha256")
        if self.lifecycle == "active":
            if (
                self.successor_project_uri is not None
                or self.relocation_authority_head_sha256 is not None
            ):
                raise ProjectAuthorityError("active locator identity carries retirement authority")
        elif self.lifecycle == "retired":
            if self.successor_project_uri is None:
                raise ProjectAuthorityError("retired locator identity lacks its successor")
            successor = canonical_project_uri(_project_path_from_uri(self.successor_project_uri))
            if successor != self.successor_project_uri or successor == self.project_uri:
                raise ProjectAuthorityError("retired locator identity successor is invalid")
            _sha(
                self.relocation_authority_head_sha256,
                "relocation_authority_head_sha256",
            )
        else:
            raise ProjectAuthorityError("locator identity lifecycle is invalid")
        if _sha(self.locator_identity_sha256, "locator_identity_sha256") != _digest(
            self._unsigned_mapping()
        ):
            raise ProjectAuthorityError("locator identity checksum is invalid")

    def _unsigned_mapping(self) -> dict[str, object]:
        return {
            name: getattr(self, name)
            for name in self.__dataclass_fields__
            if name != "locator_identity_sha256"
        }

    def to_mapping(self) -> dict[str, object]:
        return {
            **self._unsigned_mapping(),
            "locator_identity_sha256": self.locator_identity_sha256,
        }

    @classmethod
    def create_active(
        cls, *, project_uri: str, project_identity_sha256: str
    ) -> "ProjectLocatorIdentityRecord":
        unsigned = {
            "schema_name": "mif-qupath-project-locator-identity",
            "schema_version": 1,
            "project_uri": project_uri,
            "project_identity_sha256": project_identity_sha256,
            "lifecycle": "active",
            "successor_project_uri": None,
            "relocation_authority_head_sha256": None,
        }
        return cls(
            **unsigned,
            locator_identity_sha256=_digest(unsigned),
        )  # type: ignore[arg-type]

    @classmethod
    def create_retired(
        cls,
        *,
        project_uri: str,
        project_identity_sha256: str,
        successor_project_uri: str,
        relocation_authority_head_sha256: str,
    ) -> "ProjectLocatorIdentityRecord":
        unsigned = {
            "schema_name": "mif-qupath-project-locator-identity",
            "schema_version": 1,
            "project_uri": project_uri,
            "project_identity_sha256": project_identity_sha256,
            "lifecycle": "retired",
            "successor_project_uri": successor_project_uri,
            "relocation_authority_head_sha256": (relocation_authority_head_sha256),
        }
        return cls(
            **unsigned,
            locator_identity_sha256=_digest(unsigned),
        )  # type: ignore[arg-type]

    @classmethod
    def from_mapping(cls, value: object) -> "ProjectLocatorIdentityRecord":
        return cls(
            **dict(
                _closed(
                    value,
                    frozenset(cls.__dataclass_fields__),
                    "locator identity record",
                )
            )
        )  # type: ignore[arg-type]


@dataclass(frozen=True, slots=True)
class ProjectIdentityMaterializationAttestation:
    schema_name: Literal["mif-qupath-project-identity-materialization"]
    schema_version: Literal[1]
    project_identity_sha256: str
    origin_kind: Literal["created", "adopted_existing", "cloned_as_new"]
    origin_qpproj_sha256: str | None
    identity_metadata_sha256: str
    mutation_request_sha256: str
    qupath_runtime_version: str
    post_save_qpproj_snapshot_sha256: str
    materialization_attestation_sha256: str

    def __post_init__(self) -> None:
        if (
            self.schema_name != "mif-qupath-project-identity-materialization"
            or self.schema_version != 1
        ):
            raise ProjectAuthorityError("materialization schema is unsupported")
        for name in (
            "project_identity_sha256",
            "identity_metadata_sha256",
            "mutation_request_sha256",
            "post_save_qpproj_snapshot_sha256",
        ):
            _sha(getattr(self, name), name)
        _sha(self.origin_qpproj_sha256, "origin_qpproj_sha256", optional=True)
        if self.origin_kind not in {"created", "adopted_existing", "cloned_as_new"}:
            raise ProjectAuthorityError("materialization origin is invalid")
        if self.origin_kind == "created" and self.origin_qpproj_sha256 is not None:
            raise ProjectAuthorityError(
                "created materialization cannot have an origin qpproj digest"
            )
        if (
            self.origin_kind in {"adopted_existing", "cloned_as_new"}
            and self.origin_qpproj_sha256 is None
        ):
            raise ProjectAuthorityError(
                "adopted and cloned materialization require an origin qpproj digest"
            )
        _text(self.qupath_runtime_version, "qupath_runtime_version")
        if _sha(
            self.materialization_attestation_sha256, "materialization_attestation_sha256"
        ) != _digest(self._unsigned_mapping()):
            raise ProjectAuthorityError("materialization attestation checksum is not canonical")

    def _unsigned_mapping(self) -> dict[str, object]:
        return {
            name: getattr(self, name)
            for name in self.__dataclass_fields__
            if name != "materialization_attestation_sha256"
        }

    def to_mapping(self) -> dict[str, object]:
        return {
            **self._unsigned_mapping(),
            "materialization_attestation_sha256": self.materialization_attestation_sha256,
        }

    @classmethod
    def create(cls, **values: object) -> "ProjectIdentityMaterializationAttestation":
        unsigned = {
            "schema_name": "mif-qupath-project-identity-materialization",
            "schema_version": 1,
            **values,
        }
        return cls(
            **unsigned,
            materialization_attestation_sha256=_digest(unsigned),
        )  # type: ignore[arg-type]

    @classmethod
    def from_mapping(cls, value: object) -> "ProjectIdentityMaterializationAttestation":
        return cls(
            **dict(
                _closed(
                    value,
                    frozenset(cls.__dataclass_fields__),
                    "identity materialization attestation",
                )
            )
        )  # type: ignore[arg-type]


