    mutation_request_sha256: str
    mutation_authorization_sha256: str
    predecessor_authority_head_sha256: str | None
    post_save_qpproj_snapshot_sha256: str
    workspace_catalogue_sha256: str | None
    project_entry_projection_set_sha256: str
    operation_evidence_sha256: str
    mutation_attestation_sha256: str

