@dataclass(frozen=True, slots=True)
class ProjectMutationProcessLaunchRecord:
    schema_name: Literal["mif-project-mutation-process-launch"]
    schema_version: Literal[4]
    authority_layout_sha256: str
    role: Literal[
        "identity_materialization",
        "primary_mif",
        "moving_reference",
        "classifier_training",
        "registration_import",
        "transfer_qc",
    ]
    process_launch_receipt_ref: AuthorityMemberRefV2
    process_launch_current_ref: AuthorityMemberRefV2
    project_identity_sha256: str
    active_mutation_run_sha256: str
    acquisition_record_sha256: str
    acquisition_session_challenge_sha256: str
    artifact_inventory_sha256: str
    mutation_request_sha256: str
    mutation_authorization_sha256: str
    fencing_token_sha256: str
    process_start_token: QuPathProcessStartToken
    launch_evidence: ProcessContainmentLaunchEvidence
    launch_nonce_sha256: str
    spawn_attempt_sha256: str
    environment_sha256: str | None
    process_launch_sha256: str

    def __post_init__(self) -> None:
        """Validate the ProjectMutationProcessLaunchRecord fields when the record is
        constructed.

        The checks cover ``authority_layout_sha256``, ``schema_version``,
        ``project_identity_sha256``, ``active_mutation_run_sha256``, ``schema_name``,
        ``environment_sha256``. Invalid field types, values or combinations raise the
        declared validation error before this instance can be used by its caller."""

        if (
            self.schema_name != "mif-project-mutation-process-launch"
            or type(self.schema_version) is not int
            or self.schema_version != 4
        ):
            raise ProjectAuthorityError("process launch schema is unsupported")
        _sha(self.authority_layout_sha256, "authority_layout_sha256")
        if not _process_role_is_valid(schema_version=self.schema_version, role=self.role):
            raise ProjectAuthorityError("process launch role is invalid")
        for name in (
            "project_identity_sha256",
            "active_mutation_run_sha256",
            "acquisition_record_sha256",
            "acquisition_session_challenge_sha256",
            "artifact_inventory_sha256",
            "mutation_request_sha256",
            "mutation_authorization_sha256",
            "fencing_token_sha256",
            "launch_nonce_sha256",
            "spawn_attempt_sha256",
        ):
            _sha(getattr(self, name), name)
        _sha(self.environment_sha256, "environment_sha256")
        if not isinstance(self.process_start_token, QuPathProcessStartToken):
            raise ProjectAuthorityError("process launch start token is invalid")
        if type(self.launch_evidence) not in (
            LinuxSystemdScopeAttachmentV1,
            LinuxLocalProcessGroupAttachmentV1,
            WindowsKillOnCloseJobAttachmentV1,
        ):
            raise ProjectAuthorityError("process launch containment evidence is invalid")
        ref_scope = {
            "project_identity_sha256": self.project_identity_sha256,
            "active_mutation_run_sha256": self.active_mutation_run_sha256,
        }
        object.__setattr__(
            self,
            "process_launch_receipt_ref",
            _project_record_ref(
                self.process_launch_receipt_ref,
                authority_layout_sha256=self.authority_layout_sha256,
                family="project_process_launch_receipt",
                scope=ref_scope,
                natural_key={"role": self.role},
                field="process_launch_receipt_ref",
            ),
        )
        object.__setattr__(
            self,
            "process_launch_current_ref",
            _project_record_ref(
                self.process_launch_current_ref,
                authority_layout_sha256=self.authority_layout_sha256,
                family="project_process_launch_current",
                scope=ref_scope,
                natural_key={"role": self.role},
                field="process_launch_current_ref",
            ),
        )
        if type(self.launch_evidence) is LinuxSystemdScopeAttachmentV1:
            attachment = json.loads(self.launch_evidence.attachment_receipt_json_utf8)
            if (
                self.process_start_token.provider != "linux-proc-start-ticks/v1"
                or attachment["gate_pid"] != self.process_start_token.process_id
                or attachment["gate_start_token"] != str(self.process_start_token.start_ticks)
            ):
                raise ProjectAuthorityError("process launch Linux gate identity is invalid")
        if type(self.launch_evidence) is LinuxLocalProcessGroupAttachmentV1:
            if (
                self.process_start_token.provider != "linux-proc-start-ticks/v1"
                or self.launch_evidence.leader_process_id != self.process_start_token.process_id
            ):
                raise ProjectAuthorityError("process launch local group identity is invalid")
        if (
            type(self.launch_evidence) is WindowsKillOnCloseJobAttachmentV1
            and self.process_start_token.provider != "windows-process-creation-epoch-millis/v1"
        ):
            raise ProjectAuthorityError("process launch Windows identity is invalid")
        if _sha(self.process_launch_sha256, "process_launch_sha256") != _digest(
            self._unsigned_mapping()
        ):
            raise ProjectAuthorityError("process launch checksum is invalid")

    def _unsigned_mapping(self) -> dict[str, object]:
        return {
            name: (
                value.to_mapping()
                if name in {"process_start_token", "launch_evidence"}
                else (
                    value.to_mapping()
                    if name in {"process_launch_receipt_ref", "process_launch_current_ref"}
                    else value
                )
            )
            for name in self.__dataclass_fields__
            if name != "process_launch_sha256"
            for value in (getattr(self, name),)
        }

    def to_mapping(self) -> dict[str, object]:
        return {
            **self._unsigned_mapping(),
            "process_launch_sha256": self.process_launch_sha256,
        }

    @classmethod
    def create(
        cls, *, authority: ProjectAuthorityV2, **values: object
    ) -> "ProjectMutationProcessLaunchRecord":
        if not isinstance(authority, ProjectAuthorityV2):
            raise ProjectAuthorityError("process launch requires retained authority v2")
        forbidden = {
            "schema_name",
            "schema_version",
            "authority_layout_sha256",
            "process_launch_receipt_ref",
            "process_launch_current_ref",
            "environment_sha256",
            "process_launch_sha256",
        }
        if forbidden.intersection(values):
            raise ProjectAuthorityError("process launch factory fields are invalid")
        if "environment" not in values:
            raise ProjectAuthorityError("process launch environment is required")
        environment_sha256 = _environment_digest(values["environment"])
        launch_values = {name: value for name, value in values.items() if name != "environment"}
        scope = {
            "project_identity_sha256": launch_values.get("project_identity_sha256"),
            "active_mutation_run_sha256": launch_values.get("active_mutation_run_sha256"),
        }
        natural_key = {"role": launch_values.get("role")}
        unsigned = {
            "schema_name": "mif-project-mutation-process-launch",
            "schema_version": 4,
            "authority_layout_sha256": authority.authority_layout_sha256,
            "process_launch_receipt_ref": authority.ref(
                "project_process_launch_receipt",
                scope=scope,
                natural_key=natural_key,
            ),
            "process_launch_current_ref": authority.ref(
                "project_process_launch_current",
                scope=scope,
                natural_key=natural_key,
            ),
            "environment_sha256": environment_sha256,
            **launch_values,
        }
        material = dict(unsigned)
        token = material["process_start_token"]
        if not isinstance(token, QuPathProcessStartToken):
            raise ProjectAuthorityError("process launch start token is invalid")
        material["process_start_token"] = token.to_mapping()
        launch_evidence = material.get("launch_evidence")
        if type(launch_evidence) not in (
            LinuxSystemdScopeAttachmentV1,
            LinuxLocalProcessGroupAttachmentV1,
            WindowsKillOnCloseJobAttachmentV1,
        ):
            raise ProjectAuthorityError("process launch containment evidence is invalid")
        material["launch_evidence"] = launch_evidence.to_mapping()
        material["process_launch_receipt_ref"] = unsigned["process_launch_receipt_ref"].to_mapping()
        material["process_launch_current_ref"] = unsigned["process_launch_current_ref"].to_mapping()
        return cls(
            **unsigned,
            process_launch_sha256=_digest(material),
        )  # type: ignore[arg-type]

    @classmethod
    def from_mapping(cls, value: object) -> "ProjectMutationProcessLaunchRecord":
        """Decode the serialized fields into a validated ProjectMutationProcessLaunchRecord
        record.

        The parser checks the supplied mapping and converts its nested values through the
        declared constructors before constructing the record."""

        if isinstance(value, Mapping) and (
            "posix_containment" in value
            or "containment_kind" in value
            or "containment_name" in value
        ):
            raise ProjectAuthorityError(
                "incompatible security journal: retired process launch shape"
            )
        if not isinstance(value, Mapping) or type(value.get("schema_version")) is not int or value["schema_version"] != 4:
            raise ProjectAuthorityError("The saved QuPath process does not use the current launch format.")
        expected_fields = frozenset(cls.__dataclass_fields__)
        material = dict(
            _closed(
                value,
                expected_fields,
                "process launch record",
            )
        )
        material["process_start_token"] = QuPathProcessStartToken.from_mapping(
            material["process_start_token"]
        )
        try:
            for field in ("process_launch_receipt_ref", "process_launch_current_ref"):
                material[field] = AuthorityMemberRefV2.from_mapping(
                    material[field],
                    expected_layout_sha256=material["authority_layout_sha256"],  # type: ignore[arg-type]
                )
        except DurableRecordError as exc:
            raise ProjectAuthorityError("process launch ref is invalid") from exc
        try:
            raw_evidence = material["launch_evidence"]
            if not isinstance(raw_evidence, Mapping):
                raise ValueError("launch evidence is not a mapping")
            if raw_evidence.get("provider") == "linux-systemd-scope-broker/v1":
                material["launch_evidence"] = LinuxSystemdScopeAttachmentV1.from_mapping(
                    raw_evidence
                )
            elif raw_evidence.get("provider") == "linux-local-process-group/v1":
                material["launch_evidence"] = LinuxLocalProcessGroupAttachmentV1.from_mapping(
                    raw_evidence
                )
            elif raw_evidence.get("provider") == "windows-kill-on-close-job/v1":
                material["launch_evidence"] = WindowsKillOnCloseJobAttachmentV1.from_mapping(
                    raw_evidence
                )
            else:
                raise ValueError("launch evidence provider is unsupported")
        except (TypeError, ValueError) as exc:
            raise ProjectAuthorityError("process launch containment evidence is invalid") from exc
        return cls(**material)  # type: ignore[arg-type]


@dataclass(frozen=True, slots=True)
class QuPathProjectEntryEvidence:
    project_entry_id: str
    entry_name: str
    entry_path: Path
    source_uris: tuple[str, ...]
    metadata: Mapping[str, str]
    saved_state_attestation_sha256: str | None
    entry_projection_sha256: str

    def __post_init__(self) -> None:
        _text(self.project_entry_id, "project_entry_id")
        _text(self.entry_name, "entry_name")
        if not isinstance(self.entry_path, Path):
            raise ProjectMappingError("entry_path must be a Path")
        uris = tuple(sorted(_text(uri, "source_uri") for uri in self.source_uris))
        if not uris or len(set(uris)) != len(uris):
            raise ProjectMappingError("entry source URIs must be nonempty and unique")
        object.__setattr__(self, "source_uris", uris)
        object.__setattr__(self, "metadata", _string_mapping(self.metadata, "entry metadata"))
        _sha(self.saved_state_attestation_sha256, "saved_state_attestation_sha256", optional=True)
        if _sha(self.entry_projection_sha256, "entry_projection_sha256") != _digest(
            self._unsigned_mapping()
        ):
            raise ProjectMappingError("entry projection checksum is not canonical")

    def _unsigned_mapping(self) -> dict[str, object]:
        return {
            "project_entry_id": self.project_entry_id,
            "entry_name": self.entry_name,
            "entry_path": self.entry_path.as_posix(),
            "source_uris": list(self.source_uris),
            "metadata": dict(self.metadata),
            "saved_state_attestation_sha256": self.saved_state_attestation_sha256,
        }

    def to_mapping(self) -> dict[str, object]:
        return {**self._unsigned_mapping(), "entry_projection_sha256": self.entry_projection_sha256}

    @classmethod
    def create(cls, **values: object) -> "QuPathProjectEntryEvidence":
        material = dict(values)
        material["entry_path"] = Path(material["entry_path"]).as_posix()  # type: ignore[arg-type]
        material["source_uris"] = list(sorted(material["source_uris"]))  # type: ignore[arg-type]
        material["metadata"] = dict(sorted(material["metadata"].items()))  # type: ignore[union-attr]
        return cls(**values, entry_projection_sha256=_digest(material))  # type: ignore[arg-type]

    @classmethod
    def from_mapping(cls, value: object) -> "QuPathProjectEntryEvidence":
        material = dict(
            _closed(
                value,
                frozenset(
                    {
                        "project_entry_id",
                        "entry_name",
                        "entry_path",
                        "source_uris",
                        "metadata",
                        "saved_state_attestation_sha256",
                        "entry_projection_sha256",
                    }
                ),
                "QuPath project entry evidence",
            )
        )
        material["entry_path"] = Path(material["entry_path"])
        material["source_uris"] = tuple(material["source_uris"])
        return cls(**material)  # type: ignore[arg-type]


@dataclass(frozen=True, slots=True)
class QuPathProjectSnapshot:
    project_path: Path
    project_uri: str
    identity_record: ProjectIdentityRecord | None
    qpproj_sha256: str
    entries: tuple[QuPathProjectEntryEvidence, ...]

    def __post_init__(self) -> None:
        if not isinstance(self.project_path, Path):
            raise ProjectMappingError("snapshot project_path must be a Path")
        _text(self.project_uri, "project_uri")
        if self.identity_record is not None and not isinstance(
            self.identity_record, ProjectIdentityRecord
        ):
            raise ProjectIdentityError("snapshot identity record is invalid")
        _sha(self.qpproj_sha256, "qpproj_sha256")
        entries = tuple(sorted(self.entries, key=lambda entry: entry.project_entry_id))
        if not all(isinstance(entry, QuPathProjectEntryEvidence) for entry in entries):
            raise ProjectMappingError("snapshot entries must be typed")
        if len({entry.project_entry_id for entry in entries}) != len(entries):
            raise ProjectMappingError("snapshot contains duplicate string entry IDs")
        object.__setattr__(self, "entries", entries)

    @classmethod
    def create(cls, **values: object) -> "QuPathProjectSnapshot":
        return cls(**values)  # type: ignore[arg-type]

    def to_mapping(self) -> dict[str, object]:
        return {
            "project_path": self.project_path.as_posix(),
            "project_uri": self.project_uri,
            "identity_record": (
                None if self.identity_record is None else self.identity_record.to_mapping()
            ),
            "qpproj_sha256": self.qpproj_sha256,
            "entries": [entry.to_mapping() for entry in self.entries],
        }

    @classmethod
    def from_mapping(cls, value: object) -> "QuPathProjectSnapshot":
        material = dict(
            _closed(
                value,
                frozenset(
                    {
                        "project_path",
                        "project_uri",
                        "identity_record",
                        "qpproj_sha256",
                        "entries",
                    }
                ),
                "QuPath project snapshot",
            )
        )
        material["project_path"] = Path(material["project_path"])
        identity = material["identity_record"]
        material["identity_record"] = (
            None if identity is None else ProjectIdentityRecord.from_mapping(identity)
        )
        entries = material["entries"]
        if not isinstance(entries, list):
            raise ProjectMappingError("snapshot entries must be an array")
        material["entries"] = tuple(
            QuPathProjectEntryEvidence.from_mapping(entry) for entry in entries
        )
        return cls(**material)  # type: ignore[arg-type]


@dataclass(frozen=True, slots=True)
class QuPathProjectInspection:
    """Inspector-observed project plus the exact file identity it opened."""

    snapshot: QuPathProjectSnapshot
    opened_file_identity: tuple[int, int] | Win32FileIdentity

    def __post_init__(self) -> None:
        posix_identity = (
            isinstance(self.opened_file_identity, tuple)
            and len(self.opened_file_identity) == 2
            and all(type(value) is int for value in self.opened_file_identity)
            and all(value >= 0 for value in self.opened_file_identity)
        )
        if not isinstance(self.snapshot, QuPathProjectSnapshot) or not (
            posix_identity or type(self.opened_file_identity) is Win32FileIdentity
        ):
            raise ProjectMappingError("project inspection opened-file identity is invalid")


