@dataclass(frozen=True, slots=True)
class QuPathEntryUpsertRequest:
    entry_mode: Literal["reuse", "replace"]
    source_uri: str
    source_image_sha256: str
    entry_name: str
    expected_project_entry_id: str | None
    entry_metadata: Mapping[str, str]
    require_saved_state_attestation: bool

    def __post_init__(self) -> None:
        if self.entry_mode not in {"reuse", "replace"} or (self.entry_mode == "replace" and self.expected_project_entry_id is None):
            raise ProjectAuthorityError("entry replacement requires its admitted predecessor ID")
        _text(self.source_uri, "source_uri")
        _sha(self.source_image_sha256, "source_image_sha256")
        _text(self.entry_name, "entry_name")
        if self.expected_project_entry_id is not None:
            _text(self.expected_project_entry_id, "expected_project_entry_id")
        object.__setattr__(
            self, "entry_metadata", _string_mapping(self.entry_metadata, "entry_metadata")
        )
        if type(self.require_saved_state_attestation) is not bool:
            raise ProjectAuthorityError("require_saved_state_attestation must be boolean")


def _payload_mapping(payload: object) -> dict[str, object]:
    if isinstance(payload, QuPathProjectInspectRequest):
        return {"expected_project_identity_sha256": payload.expected_project_identity_sha256}
    if isinstance(payload, QuPathIdentityInstallRequest):
        return {
            "identity_record": payload.identity_record.to_mapping(),
            "create_if_missing": payload.create_if_missing,
        }
    if isinstance(payload, QuPathEntryUpsertRequest):
        return {
            "entry_mode": payload.entry_mode,
            "source_uri": payload.source_uri,
            "source_image_sha256": payload.source_image_sha256,
            "entry_name": payload.entry_name,
            "expected_project_entry_id": payload.expected_project_entry_id,
            "entry_metadata": dict(payload.entry_metadata),
            "require_saved_state_attestation": payload.require_saved_state_attestation,
        }
    raise ProjectAuthorityError("catalogue request payload is invalid")


@dataclass(frozen=True, slots=True)
class QuPathCatalogueRequestEnvelope:
    schema_name: Literal["mif-qupath-project-catalogue-request"]
    schema_version: Literal[1]
