@dataclass(frozen=True, slots=True)
class ProjectMutationAcquisitionRecord:
    schema_name: Literal["mif-project-mutation-acquisition-record"]
    schema_version: Literal[1]
    mutation_request_sha256: str
    mutation_authorization_sha256: str
    artifact_inventory_sha256: str
    operation: str
    intent: Literal["create", "open_existing", "relocate", "cloned_as_new"]
    project_uri: str
    expected_project_identity_sha256: str | None
    expected_authority_head_sha256: str | None
    recovery_predecessor_acquisition_record_sha256: str | None
    acquisition_record_sha256: str

    def __post_init__(self) -> None:
        if (
            self.schema_name != "mif-project-mutation-acquisition-record"
            or self.schema_version != 1
        ):
            raise ProjectAuthorityError("acquisition record schema is unsupported")
        for name in (
            "mutation_request_sha256",
            "mutation_authorization_sha256",
            "artifact_inventory_sha256",
        ):
            _sha(getattr(self, name), name)
        _text(self.operation, "operation")
        if self.intent not in {"create", "open_existing", "relocate", "cloned_as_new"}:
            raise ProjectAuthorityError("acquisition intent is invalid")
        _text(self.project_uri, "project_uri")
        for name in (
            "expected_project_identity_sha256",
            "expected_authority_head_sha256",
            "recovery_predecessor_acquisition_record_sha256",
        ):
            _sha(getattr(self, name), name, optional=True)
        if self.intent == "relocate" and self.expected_project_identity_sha256 is None:
            raise ProjectAuthorityError("relocation requires expected identity")
        if _sha(self.acquisition_record_sha256, "acquisition_record_sha256") != _digest(
            self._unsigned_mapping()
        ):
            raise ProjectAuthorityError("acquisition record checksum is invalid")

    def _unsigned_mapping(self) -> dict[str, object]:
        return {
            name: getattr(self, name)
            for name in self.__dataclass_fields__
            if name != "acquisition_record_sha256"
        }

    def to_mapping(self) -> dict[str, object]:
        return {
            **self._unsigned_mapping(),
            "acquisition_record_sha256": self.acquisition_record_sha256,
        }

    @classmethod
    def create(cls, **values: object) -> "ProjectMutationAcquisitionRecord":
        unsigned = {
            "schema_name": "mif-project-mutation-acquisition-record",
            "schema_version": 1,
            **values,
        }
        return cls(**unsigned, acquisition_record_sha256=_digest(unsigned))  # type: ignore[arg-type]

    @classmethod
    def from_mapping(cls, value: object) -> "ProjectMutationAcquisitionRecord":
        return cls(**dict(_closed(value, frozenset(cls.__dataclass_fields__), "acquisition record")))  # type: ignore[arg-type]


