@dataclass(frozen=True, slots=True, init=False)
class ProjectMutationProcessDrainEvidence:
    schema_name: Literal["mif-project-mutation-process-drain"]
    schema_version: Literal[4]
    authority_layout_sha256: str
    active_mutation_run_sha256: str
    role: Literal[
        "identity_materialization",
        "primary_mif",
        "moving_reference",
        "classifier_training",
        "registration_import",
        "transfer_qc",
    ]
    process_drain_ref: AuthorityMemberRefV2
    project_identity_sha256: str
    acquisition_record_sha256: str
    acquisition_session_challenge_sha256: str
    mutation_request_sha256: str
    fencing_token_sha256: str
    process_start_token: QuPathProcessStartToken | None
    launch_nonce_sha256: str | None
    terminal_status_sha256: str | None
    drain_evidence: ProcessContainmentDrainEvidence | None
    spawn_attempt_sha256: str | None
    process_launch_sha256: str | None
    containment_drained: bool
    process_drain_sha256: str
    _issuer: object

    @classmethod
    def _issue(
        cls,
        *,
        issuer: object,
        authority: ProjectAuthorityV2 | None = None,
        _from_current_mapping: bool = False,
        **values: object,
    ) -> "ProjectMutationProcessDrainEvidence":
        if authority is None and not _from_current_mapping:
            raise ProjectAuthorityError("process drain requires retained authority v2")
        supplied_schema_name = values.pop("schema_name", None)
        supplied_schema_version = values.pop("schema_version", None)
        if _from_current_mapping:
            if (
                supplied_schema_name != "mif-project-mutation-process-drain"
                or type(supplied_schema_version) is not int
                or supplied_schema_version != 4
            ):
                raise ProjectAuthorityError("process drain schema is unsupported")
        elif supplied_schema_name is not None or supplied_schema_version is not None:
            raise ProjectAuthorityError("process drain issuer fields are invalid")
        if authority is not None and {
            "authority_layout_sha256",
            "process_drain_ref",
        }.intersection(values):
            raise ProjectAuthorityError("process drain issuer fields are invalid")
        scope = {
            "project_identity_sha256": values.get("project_identity_sha256"),
            "active_mutation_run_sha256": values.get("active_mutation_run_sha256"),
        }
        natural_key = {"role": values.get("role")}
        authority_fields = (
            {
                "authority_layout_sha256": values.pop("authority_layout_sha256"),
                "process_drain_ref": values.pop("process_drain_ref"),
            }
            if authority is None
            else {
                "authority_layout_sha256": authority.authority_layout_sha256,
                "process_drain_ref": authority.ref(
                    "project_process_drain", scope=scope, natural_key=natural_key
                ),
            }
        )
        unsigned = {
            "schema_name": "mif-project-mutation-process-drain",
            "schema_version": 4,
            **authority_fields,
            **values,
        }
        for name in (
            "authority_layout_sha256",
            "project_identity_sha256",
            "active_mutation_run_sha256",
            "acquisition_record_sha256",
            "acquisition_session_challenge_sha256",
            "mutation_request_sha256",
            "fencing_token_sha256",
        ):
            _sha(unsigned[name], name)
        preparation_only = unsigned["role"] == "project_stage_preparation"
        if not preparation_only and not _process_role_is_valid(
            schema_version=unsigned["schema_version"],  # type: ignore[arg-type]
            role=unsigned["role"],
        ):
            raise ProjectAuthorityError("process drain role is invalid")
        unsigned["process_drain_ref"] = _project_record_ref(
            unsigned["process_drain_ref"],
            authority_layout_sha256=unsigned["authority_layout_sha256"],  # type: ignore[arg-type]
            family="project_process_drain",
            scope=scope,
            natural_key=natural_key,
            field="process_drain_ref",
        )
        if type(unsigned["containment_drained"]) is not bool:
            raise ProjectAuthorityError("process drain evidence is invalid")
        token = unsigned["process_start_token"]
        if token is not None and not isinstance(token, QuPathProcessStartToken):
            raise ProjectAuthorityError("process drain start token is invalid")
        for name in (
            "launch_nonce_sha256",
            "terminal_status_sha256",
            "spawn_attempt_sha256",
            "process_launch_sha256",
        ):
            _sha(unsigned[name], name, optional=True)
        drain_evidence = unsigned["drain_evidence"]
        if preparation_only and drain_evidence is not None:
            raise ProjectAuthorityError("project-stage preparation cannot carry a process drain")
        if drain_evidence is not None and type(drain_evidence) not in (
            LinuxSystemdScopeDrainV1,
            LinuxLocalProcessGroupDrainV1,
            WindowsKillOnCloseJobDrainV1,
        ):
            raise ProjectAuthorityError("process drain backend evidence is invalid")
        if drain_evidence is None and (
            token is not None
            or unsigned["launch_nonce_sha256"] is not None
            or unsigned["terminal_status_sha256"] is not None
            or unsigned["spawn_attempt_sha256"] is not None
            or unsigned["process_launch_sha256"] is not None
            or unsigned["containment_drained"] is not True
        ):
            raise ProjectAuthorityError("no-process drain evidence is inconsistent")
        if drain_evidence is not None and (
            token is None
            or unsigned["launch_nonce_sha256"] is None
            or unsigned["terminal_status_sha256"] is None
            or unsigned["spawn_attempt_sha256"] is None
            or unsigned["containment_drained"] is not True
        ):
            raise ProjectAuthorityError("launched-process drain evidence is incomplete")
        if (
            drain_evidence is not None
            and unsigned["process_launch_sha256"] is None
            and drain_evidence.termination_reason != "launch_publication_failed"
        ):
            raise ProjectAuthorityError(
                "launched-process drain lacks its process-launch predecessor"
            )
        if (
            type(drain_evidence) is LinuxSystemdScopeDrainV1
            and unsigned["process_launch_sha256"] is None
            and (
                drain_evidence.release_receipt_json_utf8 is not None
                or drain_evidence.release_receipt_sha256 is not None
            )
        ):
            raise ProjectAuthorityError("pre-release Linux drain cannot carry release evidence")
        material = dict(unsigned)
        material["process_start_token"] = None if token is None else token.to_mapping()
        material["drain_evidence"] = None if drain_evidence is None else drain_evidence.to_mapping()
        material["process_drain_ref"] = unsigned["process_drain_ref"].to_mapping()
        return _issue_opaque(
            cls,
            **unsigned,
            process_drain_sha256=_digest(material),
            _issuer=issuer,
        )  # type: ignore[return-value]

    def to_mapping(self) -> dict[str, object]:
        return {
            name: (
                None
                if name == "process_start_token" and value is None
                else (
                    value.to_mapping()
                    if name == "process_start_token"
                    else (
                        value.to_mapping()
                        if name == "drain_evidence" and value is not None
                        else value.to_mapping() if name == "process_drain_ref" else value
                    )
                )
            )
            for name in self.__slots__
            if name != "_issuer"
            for value in (getattr(self, name),)
        }

    @classmethod
    def _from_mapping(
        cls, value: object, *, issuer: object
    ) -> "ProjectMutationProcessDrainEvidence":
        if isinstance(value, Mapping) and "containment_kind" in value:
            raise ProjectAuthorityError(
                "incompatible security journal: retired process drain shape"
            )
        fields = frozenset(name for name in cls.__slots__ if name != "_issuer")
        material = dict(_closed(value, fields, "process drain evidence"))
        claimed = material.pop("process_drain_sha256")
        try:
            material["process_drain_ref"] = AuthorityMemberRefV2.from_mapping(
                material["process_drain_ref"],
                expected_layout_sha256=material["authority_layout_sha256"],  # type: ignore[arg-type]
            )
        except DurableRecordError as exc:
            raise ProjectAuthorityError("process drain ref is invalid") from exc
        raw_token = material.get("process_start_token")
        material["process_start_token"] = (
            None if raw_token is None else QuPathProcessStartToken.from_mapping(raw_token)
        )
        raw_drain = material.get("drain_evidence")
        try:
            if raw_drain is None:
                material["drain_evidence"] = None
            elif not isinstance(raw_drain, Mapping):
                raise ValueError("drain evidence is not a mapping")
            elif raw_drain.get("provider") == "linux-systemd-scope-broker/v1":
                material["drain_evidence"] = LinuxSystemdScopeDrainV1.from_mapping(raw_drain)
            elif raw_drain.get("provider") == "linux-local-process-group/v1":
                material["drain_evidence"] = LinuxLocalProcessGroupDrainV1.from_mapping(raw_drain)
            elif raw_drain.get("provider") == "windows-kill-on-close-job/v1":
                material["drain_evidence"] = WindowsKillOnCloseJobDrainV1.from_mapping(raw_drain)
            else:
                raise ValueError("drain evidence provider is unsupported")
        except (TypeError, ValueError) as exc:
            raise ProjectAuthorityError("process drain backend evidence is invalid") from exc
        result = cls._issue(
            issuer=issuer,
            authority=None,
            _from_current_mapping=True,
            **material,
        )
        if result.process_drain_sha256 != claimed:
            raise ProjectAuthorityError("process drain checksum is invalid")
        return result


@dataclass(frozen=True, slots=True)
class ProjectMutationArtifactObservation:
    target_sha256: str
    resolved_locator_uri: str
    locator_sha256: str
    predecessor_sha256: str | None
    observed_sha256: str | None
    disposition: Literal[
        "absent",
        "unchanged_predecessor",
        "rolled_back_to_predecessor",
        "immutable_orphan_not_current",
    ]
    observation_sha256: str

    def __post_init__(self) -> None:
        _sha(self.target_sha256, "target_sha256")
        _text(self.resolved_locator_uri, "resolved_locator_uri")
        _sha(self.locator_sha256, "locator_sha256")
        _sha(self.predecessor_sha256, "predecessor_sha256", optional=True)
        _sha(self.observed_sha256, "observed_sha256", optional=True)
        if self.disposition not in {
            "absent",
            "unchanged_predecessor",
            "rolled_back_to_predecessor",
            "immutable_orphan_not_current",
        }:
            raise ProjectAuthorityError("artifact observation disposition is invalid")
        if self.disposition == "absent" and self.observed_sha256 is not None:
            raise ProjectAuthorityError("absent observation cannot carry bytes")
        if self.disposition in {"unchanged_predecessor", "rolled_back_to_predecessor"} and (
            self.predecessor_sha256 is None or self.observed_sha256 != self.predecessor_sha256
        ):
            raise ProjectAuthorityError("predecessor observation is inconsistent")
        if _sha(self.observation_sha256, "observation_sha256") != _digest(self._unsigned_mapping()):
            raise ProjectAuthorityError("artifact observation checksum is invalid")

    def _unsigned_mapping(self) -> dict[str, object]:
        return {
            name: getattr(self, name)
            for name in self.__dataclass_fields__
            if name != "observation_sha256"
        }

    def to_mapping(self) -> dict[str, object]:
        return {**self._unsigned_mapping(), "observation_sha256": self.observation_sha256}

    @classmethod
    def create(cls, **values: object) -> "ProjectMutationArtifactObservation":
        return cls(**values, observation_sha256=_digest(values))  # type: ignore[arg-type]

    @classmethod
    def from_mapping(cls, value: object) -> "ProjectMutationArtifactObservation":
        return cls(**dict(_closed(value, frozenset(cls.__dataclass_fields__), "artifact observation")))  # type: ignore[arg-type]


@dataclass(frozen=True, slots=True, init=False)
class ProjectMutationArtifactClassification:
    schema_name: Literal["mif-project-mutation-artifact-classification"]
    schema_version: Literal[1]
    project_identity_sha256: str
    acquisition_record_sha256: str
    acquisition_session_challenge_sha256: str
    mutation_request_sha256: str
    mutation_authorization_sha256: str
    artifact_inventory_sha256: str
    artifact_resolution_evidence_sha256: str
    observations: tuple[ProjectMutationArtifactObservation, ...]
    classification_sha256: str
    _issuer: object

    @classmethod
    def _issue(cls, *, issuer: object, **values: object) -> "ProjectMutationArtifactClassification":
        observations = tuple(
            sorted(values.pop("observations"), key=lambda item: item.target_sha256)
        )
        if not all(isinstance(item, ProjectMutationArtifactObservation) for item in observations):
            raise ProjectAuthorityError("artifact observations must be typed")
        if len({item.target_sha256 for item in observations}) != len(observations):
            raise ProjectAuthorityError("artifact observations are not unique")
        unsigned = {
            "schema_name": "mif-project-mutation-artifact-classification",
            "schema_version": 1,
            **values,
            "observations": observations,
        }
        for name in (
            "project_identity_sha256",
            "acquisition_record_sha256",
            "acquisition_session_challenge_sha256",
            "mutation_request_sha256",
            "mutation_authorization_sha256",
            "artifact_inventory_sha256",
            "artifact_resolution_evidence_sha256",
        ):
            _sha(unsigned[name], name)
        material = {**unsigned, "observations": [item.to_mapping() for item in observations]}
        return _issue_opaque(
            cls, **unsigned, classification_sha256=_digest(material), _issuer=issuer
        )  # type: ignore[return-value]

    def to_mapping(self) -> dict[str, object]:
        return {
            name: [item.to_mapping() for item in value] if name == "observations" else value
            for name in self.__slots__
            if name != "_issuer"
            for value in (getattr(self, name),)
        }

    @classmethod
    def _from_mapping(
        cls, value: object, *, issuer: object
    ) -> "ProjectMutationArtifactClassification":
        fields = frozenset(name for name in cls.__slots__ if name != "_issuer")
        material = dict(_closed(value, fields, "artifact classification"))
        claimed = material.pop("classification_sha256")
        raw = material.pop("observations")
        if not isinstance(raw, list):
            raise ProjectAuthorityError("artifact observations must be an array")
        result = cls._issue(
            issuer=issuer,
            observations=tuple(
                ProjectMutationArtifactObservation.from_mapping(item) for item in raw
            ),
            **material,
        )
        if result.classification_sha256 != claimed:
            raise ProjectAuthorityError("artifact classification checksum is invalid")
        return result


@dataclass(frozen=True, slots=True, init=False)
class ProjectMutationAbortEvidence:
    schema_name: Literal["mif-project-mutation-abort-evidence"]
    schema_version: Literal[2]
    authority_layout_sha256: str
    active_mutation_run_sha256: str
    abort_finalization_ref: AuthorityMemberRefV2
    mutation_request_sha256: str
    mutation_authorization_sha256: str
    project_identity_sha256: str
    acquisition_record_sha256: str
    acquisition_session_challenge_sha256: str
    artifact_resolution_evidence_sha256: str
    fencing_token_sha256: str
    process_drain_sha256: str
    artifact_classification_sha256: str
    observed_project_authority_head_sha256: str | None
    observed_batch_state_head_sha256: str | None
    evidence_sha256: str
    _issuer: object

    @classmethod
    def _issue(
        cls,
        *,
        issuer: object,
        authority: ProjectAuthorityV2 | None = None,
        _from_current_mapping: bool = False,
        **values: object,
    ) -> "ProjectMutationAbortEvidence":
        if authority is None and not _from_current_mapping:
            raise ProjectAuthorityError("abort finalization requires retained authority v2")
        supplied_schema_name = values.pop("schema_name", None)
        supplied_schema_version = values.pop("schema_version", None)
        if _from_current_mapping:
            if (
                supplied_schema_name != "mif-project-mutation-abort-evidence"
                or supplied_schema_version != 2
            ):
                raise ProjectAuthorityError("project abort evidence schema is unsupported")
        elif supplied_schema_name is not None or supplied_schema_version is not None:
            raise ProjectAuthorityError("project abort issuer fields are invalid")
        if authority is not None and {
            "authority_layout_sha256",
            "abort_finalization_ref",
        }.intersection(values):
            raise ProjectAuthorityError("project abort issuer fields are invalid")
        scope = {
            "project_identity_sha256": values.get("project_identity_sha256"),
            "active_mutation_run_sha256": values.get("active_mutation_run_sha256"),
        }
        authority_fields = (
            {
                "authority_layout_sha256": values.pop("authority_layout_sha256"),
                "abort_finalization_ref": values.pop("abort_finalization_ref"),
            }
            if authority is None
            else {
                "authority_layout_sha256": authority.authority_layout_sha256,
                "abort_finalization_ref": authority.ref(
                    "project_abort_finalization", scope=scope, natural_key={}
                ),
            }
        )
        unsigned = {
            "schema_name": "mif-project-mutation-abort-evidence",
            "schema_version": 2,
            **authority_fields,
            **values,
        }
        for name in (
            "authority_layout_sha256",
            "active_mutation_run_sha256",
            "mutation_request_sha256",
            "mutation_authorization_sha256",
            "project_identity_sha256",
            "acquisition_record_sha256",
            "acquisition_session_challenge_sha256",
            "artifact_resolution_evidence_sha256",
            "fencing_token_sha256",
            "process_drain_sha256",
            "artifact_classification_sha256",
        ):
            _sha(unsigned[name], name)
        unsigned["abort_finalization_ref"] = _project_record_ref(
            unsigned["abort_finalization_ref"],
            authority_layout_sha256=unsigned["authority_layout_sha256"],  # type: ignore[arg-type]
            family="project_abort_finalization",
            scope=scope,
            natural_key={},
            field="abort_finalization_ref",
        )
        for name in (
            "observed_project_authority_head_sha256",
            "observed_batch_state_head_sha256",
        ):
            _sha(unsigned[name], name, optional=True)
        material = {
            **unsigned,
            "abort_finalization_ref": unsigned["abort_finalization_ref"].to_mapping(),
        }
        return _issue_opaque(
            cls, **unsigned, evidence_sha256=_digest(material), _issuer=issuer
        )  # type: ignore[return-value]

    def to_mapping(self) -> dict[str, object]:
        return {
            name: value.to_mapping() if name == "abort_finalization_ref" else value
            for name in self.__slots__
            if name != "_issuer"
            for value in (getattr(self, name),)
        }

    @classmethod
    def _from_mapping(cls, value: object, *, issuer: object) -> "ProjectMutationAbortEvidence":
        fields = frozenset(name for name in cls.__slots__ if name != "_issuer")
        material = dict(_closed(value, fields, "project abort evidence"))
        claimed = material.pop("evidence_sha256")
        try:
            material["abort_finalization_ref"] = AuthorityMemberRefV2.from_mapping(
                material["abort_finalization_ref"],
                expected_layout_sha256=material["authority_layout_sha256"],  # type: ignore[arg-type]
            )
        except DurableRecordError as exc:
            raise ProjectAuthorityError("abort finalization ref is invalid") from exc
        result = cls._issue(
            issuer=issuer,
            authority=None,
            _from_current_mapping=True,
            **material,
        )
        if result.evidence_sha256 != claimed:
            raise ProjectAuthorityError("project abort evidence checksum is invalid")
        return result


@dataclass(frozen=True, slots=True)
class PreStateProjectRecoveryDiscovery:
    recovery_kind: str
    project_path: Path
