    active_planned_resolution_json_utf8: str | None
    active_planned_resolution_bytes_sha256: str | None
    active_planned_resolution_target_descriptors: tuple[ProjectMutationArtifactTarget, ...] | None
    published_resolution_evidence_sha256: str | None
