@dataclass(frozen=True, slots=True, init=False)
class ProjectMutationArtifactResolutionEvidence:
    schema_name: Literal["mif-project-mutation-artifact-resolution"]
    schema_version: Literal[1]
    acquisition_record_sha256: str
    artifact_inventory_sha256: str
    project_identity_sha256: str
    predecessor_resolution_evidence_sha256: str | None
    resolved_targets: tuple[ProjectMutationResolvedArtifactTarget, ...]
    unresolved_target_sha256s: tuple[str, ...]
    resolution_evidence_sha256: str
    _provider_issuer: object

    @classmethod
    def _issue(
        cls,
        *,
        provider_issuer: object,
        acquisition_record_sha256: str,
        artifact_inventory_sha256: str,
        project_identity_sha256: str,
        predecessor_resolution_evidence_sha256: str | None,
        resolved_targets: tuple[ProjectMutationResolvedArtifactTarget, ...],
        unresolved_target_sha256s: tuple[str, ...],
    ) -> "ProjectMutationArtifactResolutionEvidence":
        resolved = tuple(sorted(resolved_targets, key=lambda item: item.target_sha256))
        unresolved = tuple(
            sorted(_sha(item, "unresolved target") for item in unresolved_target_sha256s)
        )
        unsigned = {
            "schema_name": "mif-project-mutation-artifact-resolution",
            "schema_version": 1,
            "acquisition_record_sha256": _sha(
                acquisition_record_sha256, "acquisition_record_sha256"
            ),
            "artifact_inventory_sha256": _sha(
                artifact_inventory_sha256, "artifact_inventory_sha256"
            ),
            "project_identity_sha256": _sha(project_identity_sha256, "project_identity_sha256"),
            "predecessor_resolution_evidence_sha256": _sha(
                predecessor_resolution_evidence_sha256,
                "predecessor_resolution_evidence_sha256",
                optional=True,
            ),
            "resolved_targets": resolved,
            "unresolved_target_sha256s": unresolved,
        }
        material = {
            **unsigned,
            "resolved_targets": [item.to_mapping() for item in resolved],
            "unresolved_target_sha256s": list(unresolved),
        }
        return _issue_opaque(
            cls,
            **unsigned,
            resolution_evidence_sha256=_digest(material),
            _provider_issuer=provider_issuer,
        )  # type: ignore[return-value]

    def to_mapping(self) -> dict[str, object]:
        return {
            "schema_name": self.schema_name,
            "schema_version": self.schema_version,
            "acquisition_record_sha256": self.acquisition_record_sha256,
            "artifact_inventory_sha256": self.artifact_inventory_sha256,
            "project_identity_sha256": self.project_identity_sha256,
            "predecessor_resolution_evidence_sha256": self.predecessor_resolution_evidence_sha256,
            "resolved_targets": [item.to_mapping() for item in self.resolved_targets],
            "unresolved_target_sha256s": list(self.unresolved_target_sha256s),
            "resolution_evidence_sha256": self.resolution_evidence_sha256,
        }

    @classmethod
    def _from_mapping(
        cls, value: object, *, provider_issuer: object
    ) -> "ProjectMutationArtifactResolutionEvidence":
        mapping = _closed(
            value,
            frozenset(
                {
                    "schema_name",
                    "schema_version",
                    "acquisition_record_sha256",
                    "artifact_inventory_sha256",
                    "project_identity_sha256",
                    "predecessor_resolution_evidence_sha256",
                    "resolved_targets",
                    "unresolved_target_sha256s",
                    "resolution_evidence_sha256",
                }
            ),
            "artifact resolution evidence",
        )
        resolved = mapping["resolved_targets"]
        unresolved = mapping["unresolved_target_sha256s"]
        if not isinstance(resolved, list) or not isinstance(unresolved, list):
            raise ProjectAuthorityError("artifact resolution target sets are invalid")
        result = cls._issue(
            provider_issuer=provider_issuer,
            acquisition_record_sha256=mapping["acquisition_record_sha256"],  # type: ignore[arg-type]
            artifact_inventory_sha256=mapping["artifact_inventory_sha256"],  # type: ignore[arg-type]
            project_identity_sha256=mapping["project_identity_sha256"],  # type: ignore[arg-type]
            predecessor_resolution_evidence_sha256=mapping[
                "predecessor_resolution_evidence_sha256"
            ],  # type: ignore[arg-type]
            resolved_targets=tuple(
                ProjectMutationResolvedArtifactTarget.from_mapping(item) for item in resolved
            ),
            unresolved_target_sha256s=tuple(unresolved),  # type: ignore[arg-type]
        )
        if result.resolution_evidence_sha256 != mapping["resolution_evidence_sha256"]:
            raise ProjectAuthorityError("artifact resolution checksum is invalid")
        return result


class _ProjectFileLock:
    def __init__(self, path: Path) -> None:
        self.path = path
        self.stream = None

    @property
    def descriptor(self) -> int:
        if self.stream is None:
            raise ProjectMutationConflictError("project lock is not live")
        return self.stream.fileno()

    def acquire(self, *, blocking: bool = False) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        parent_status = self.path.parent.lstat()
        reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
        if (
            stat.S_ISLNK(parent_status.st_mode)
            or getattr(parent_status, "st_file_attributes", 0) & reparse_flag
            or not stat.S_ISDIR(parent_status.st_mode)
        ):
            raise ProjectAuthorityError("project lock parent is unsafe")
        if self.path.exists() or self.path.is_symlink():
            carrier_status = self.path.lstat()
            if (
                stat.S_ISLNK(carrier_status.st_mode)
                or getattr(carrier_status, "st_file_attributes", 0) & reparse_flag
            ):
                raise ProjectAuthorityError(
                    "project lock carrier cannot be a symlink or reparse point"
                )
        flags = os.O_RDWR | os.O_CREAT
        flags |= getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        try:
            descriptor = os.open(self.path, flags, 0o600)
        except OSError as exc:
            raise ProjectAuthorityError("project lock carrier cannot be opened safely") from exc
        stream = os.fdopen(descriptor, "r+b", buffering=0)
        try:
            status = os.fstat(stream.fileno())
            if (
                not stat.S_ISREG(status.st_mode)
                or status.st_nlink != 1
                or getattr(status, "st_file_attributes", 0) & reparse_flag
            ):
                raise ProjectAuthorityError("project lock carrier must be one regular file")
            if status.st_size == 0:
                stream.write(b"\0")
                stream.flush()
                os.fsync(stream.fileno())
            stream.seek(0)
            if os.name == "posix":
                import fcntl

                flags = fcntl.LOCK_EX
                if not blocking:
                    flags |= fcntl.LOCK_NB
                fcntl.flock(stream.fileno(), flags)
            elif os.name == "nt":
                import msvcrt

                stream.seek(0)
                msvcrt.locking(
                    stream.fileno(),
                    msvcrt.LK_LOCK if blocking else msvcrt.LK_NBLCK,
                    1,
                )
            else:
                raise ProjectAuthorityError(f"project locking unsupported on {os.name!r}")
        except ProjectAuthorityError:
            stream.close()
            raise
        except (BlockingIOError, OSError) as exc:
            stream.close()
            raise ProjectMutationConflictError("project mutation lock is held") from exc
        self.stream = stream

    def release(self) -> None:
        if self.stream is None:
            return
        try:
            if os.name == "posix":
                import fcntl

                fcntl.flock(self.stream.fileno(), fcntl.LOCK_UN)
            elif os.name == "nt":
                import msvcrt

                self.stream.seek(0)
                msvcrt.locking(self.stream.fileno(), msvcrt.LK_UNLCK, 1)
        finally:
            self.stream.close()
            self.stream = None


@dataclass(frozen=True, slots=True)
class ProjectMutationLeaseRecord:
    schema_name: Literal["mif-project-mutation-lease"]
